function FinpayLanding({ go }) {
  const scrollToSection = (id) => {
    const section = document.getElementById(id);
    if (!section) return;
    const sectionTop = window.scrollY + section.getBoundingClientRect().top;
    const availableSpace = window.innerHeight - section.offsetHeight;
    const topInset = id === "student-tools" ? 72 : Math.max(24, availableSpace / 2);
    window.scrollTo({ top: Math.max(0, sectionTop - topInset), left: 0, behavior: "smooth" });
  };
  const steps = [
    ["01", "Set your direction", "Build a profile around the skills, goals, and experience that matter to you."],
    ["02", "Prepare your evidence", "Create CV versions and keep the right document ready for each application."],
    ["03", "Move with clarity", "Discover opportunities, apply with confidence, and keep every next step visible."],
  ];
  useEffect(() => {
    const items = [...document.querySelectorAll(".cf-landing .cf-reveal")];
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { items.forEach((item) => item.classList.add("is-visible")); return undefined; }
    const updateMotion = () => { const triggerLine = window.innerHeight * .7; const atPageEnd = window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 4; items.forEach((item) => { const box = item.getBoundingClientRect(); item.classList.toggle("is-visible", (box.top <= triggerLine && box.bottom >= 0) || (atPageEnd && box.top < window.innerHeight)); }); };
    updateMotion(); window.addEventListener("scroll", updateMotion, { passive: true }); window.addEventListener("resize", updateMotion);
    return () => { window.removeEventListener("scroll", updateMotion); window.removeEventListener("resize", updateMotion); };
  }, []);

  return <main className="cf-landing">
    <header className="cf-header cf-reveal cf-fade">
      <Brand onClick={() => go("/")} />
      <nav aria-label="Main navigation">
        <button type="button" onClick={() => scrollToSection("how-it-works")}>How it works</button>
        <button type="button" onClick={() => scrollToSection("student-tools")}>Student tools</button>
        <button type="button" onClick={() => scrollToSection("why-careerforge")}>Why CareerForge</button>
      </nav>
      <div className="cf-header-actions">
        <button className="cf-login" type="button" onClick={() => go("/login/student")}>Sign in</button>
        <Button onClick={() => go("/register")}>Create workspace <ArrowRight size={15} /></Button>
      </div>
    </header>

    <section className="cf-hero">
      <div className="cf-hero-copy cf-reveal cf-from-left">
              <p className="cf-eyebrow">Career tools for focused students</p>
        <h1>Turn your next step<br />into a <em>clear plan.</em></h1>
        <p className="cf-lede">CareerForge brings your profile, CVs, opportunities, and applications into one calm workspace—so you can spend less time organising and more time moving forward.</p>
        <div className="cf-hero-actions">
          <Button onClick={() => go("/register")}>Create your workspace <ArrowRight size={16} /></Button>
          <button className="cf-text-action" type="button" onClick={() => scrollToSection("how-it-works")}>See how it works <ArrowRight size={15} /></button>
        </div>
        <div className="cf-hero-proof" aria-label="CareerForge highlights">
          <span><ShieldCheck size={16} /> One secure workspace</span>
          <span><FileText size={16} /> CVs ready to use</span>
          <span><BriefcaseBusiness size={16} /> Real opportunities</span>
        </div>
      </div>

      <div className="cf-hero-visual cf-reveal cf-from-right" aria-label="Student building her career at a laptop">
        <figure className="cf-student-photo"><img src={jobSearchStudentPhoto} alt="Bangladeshi student exploring career opportunities on a laptop" /></figure>
        <div className="cf-photo-tint" aria-hidden="true" />
        <article className="cf-photo-story"><span><Target size={16} /></span><div><small>CAREER JOURNEY</small><b>Build a plan that feels like yours.</b></div></article>
        <article className="cf-floating-card cf-floating-profile"><span><FileText size={16} /></span><div><small>CV VERSION</small><b>Frontend portfolio</b></div><em>Ready</em></article>
        <article className="cf-floating-card cf-floating-match"><span><Target size={16} /></span><div><small>TOP MATCH</small><b>Junior UI Designer</b></div><strong>92%</strong></article>
      </div>
    </section>

    <section className="cf-value-strip" id="student-tools">
      <article className="cf-reveal cf-from-bottom" style={{ "--cf-delay": "0ms" }}><span><CircleUserRound size={19} /></span><div><b>Tell your story once</b><p>Keep your education, skills, goals, and experience organised in one profile.</p></div></article>
      <article className="cf-reveal cf-from-bottom" style={{ "--cf-delay": "120ms" }}><span><FileText size={19} /></span><div><b>Use the right CV</b><p>Create and choose a polished CV version for each opportunity.</p></div></article>
      <article className="cf-reveal cf-from-bottom" style={{ "--cf-delay": "240ms" }}><span><BriefcaseBusiness size={19} /></span><div><b>Know your next move</b><p>Explore roles and keep every application visible from one place.</p></div></article>
    </section>

    <section className="cf-section cf-steps-section" id="how-it-works">
      <div className="cf-section-intro cf-reveal cf-from-left"><p className="cf-eyebrow">A simple career rhythm</p><h2>Small steps.<br /><em>Meaningful progress.</em></h2><p>CareerForge turns a scattered job search into a system you can understand, use, and return to.</p></div>
      <div className="cf-steps">{steps.map(([number, title, copy], index) => <article className="cf-reveal cf-from-bottom" style={{ "--cf-delay": `${index * 120}ms` }} key={number}><span>{number}</span><h3>{title}</h3><p>{copy}</p><button type="button" onClick={() => go(number === "01" ? "/register" : "/login/student")}>Open tool <ArrowRight size={15} /></button></article>)}</div>
    </section>

    <section className="cf-feature-panel" id="why-careerforge">
      <div className="cf-feature-copy cf-reveal cf-from-left"><p className="cf-eyebrow">Designed for momentum</p><h2>Everything you need.<br /><em>Nothing in your way.</em></h2><p>Every screen is designed around a practical question: what will help you make your next career decision with more confidence?</p><Button onClick={() => go("/register")}>Start your profile <ArrowRight size={15} /></Button></div>
      <div className="cf-action-list cf-reveal cf-from-right" aria-label="CareerForge actions">
        <header><span>YOUR ACTION PLAN</span><small>This week</small></header>
        <article><b>01</b><div><strong>Define your target role</strong><small>Set a direction for your search</small></div><span className="cf-status is-done">Done</span></article>
        <article><b>02</b><div><strong>Build a CV version</strong><small>Make your experience easy to share</small></div><ArrowRight size={16} /></article>
        <article><b>03</b><div><strong>Review job matches</strong><small>12 opportunities are waiting</small></div><ArrowRight size={16} /></article>
        <footer><span>ONE PLACE FOR EVERY NEXT STEP</span><ArrowRight size={15} /></footer>
      </div>
    </section>

    <section className="cf-final-cta cf-reveal cf-from-bottom">
      <div><p className="cf-eyebrow">Your career, made clearer</p><h2>Build a future you<br />can <em>move toward.</em></h2><p>Create a student workspace and take the next step with a plan behind you.</p></div>
      <div className="cf-final-actions"><Button onClick={() => go("/register")}>Create free workspace <ArrowRight size={16} /></Button><button type="button" onClick={() => go("/login/student")}>I already have an account</button></div>
    </section>

    <footer className="cf-footer cf-reveal cf-fade"><Brand onClick={() => go("/")} /><span>CareerForge · Advanced Object Oriented Programming Laboratory</span><button type="button" onClick={() => go("/login/admin")}>Administrator sign in</button></footer>
  </main>;
}

function Login({ role, register, go }) {
  const admin = role === "admin";
  const variant = register ? "register" : admin ? "admin" : "student";
  const authPhoto = register ? registerStudentPhoto : admin ? adminCareerServicesPhoto : studentLoginPhoto;
  const authPhotoAlt = register ? "Bangladeshi student preparing her career workspace" : admin ? "Bangladeshi career-services administrator at work" : "Bangladeshi student planning a job search";
  const authView = register
    ? { eyebrow: "Your career workspace", title: "Start with a clear direction.", copy: "Set up one focused space for your profile, CVs, and the opportunities ahead.", boardLabel: "YOUR FIRST THREE STEPS", boardValue: "01", rows: [[Target, "Set your direction", "Choose a role that interests you", "Start"], [FileText, "Prepare your CV", "Add evidence when you are ready", "Next"], [BriefcaseBusiness, "See matching roles", "Keep every application in view", "Then"]] }
    : admin
      ? { eyebrow: "Operations workspace", title: "Keep opportunity moving.", copy: "Publish meaningful roles, manage applications, and support every student journey.", boardLabel: "OPPORTUNITY DESK", boardValue: "12", rows: [[BriefcaseBusiness, "Published roles", "Opportunities ready to discover", "Live"], [Users, "Student applications", "Review every next step", "Review"], [ClipboardCheck, "Platform activity", "Keep the experience on track", "Today"]] }
      : { eyebrow: "Your career workspace", title: "Make progress feel possible.", copy: "Keep your education, goals, CVs, and professional story together in one place.", boardLabel: "CAREER READINESS", boardValue: "72%", rows: [[CircleUserRound, "Your profile", "Your strengths in one clear view", "Active"], [FileText, "CV version", "A polished document, ready to use", "Ready"], [Target, "Next career move", "Discover opportunities with focus", "Explore"]] };
  const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [message, setMessage] = useState(""); const [submitting, setSubmitting] = useState(false);
  async function submit(event) { event.preventDefault(); setSubmitting(true); setMessage(""); try { const response = await fetch(`${API_BASE_URL}${register ? "/auth/register" : "/auth/login"}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(register ? { name: name.trim(), email: email.trim(), password } : { email: email.trim(), password, role: admin ? "admin" : "student" }) }); const body = await responseBody(response); localStorage.setItem("careerforge_session", JSON.stringify(body)); go(`/${body.role}/overview`); } catch (error) { setMessage(error.message || "Unable to sign in."); } finally { setSubmitting(false); } }
  return <main className={`auth-page auth-${variant}`}>
    <section className="auth-card">
      <form className="auth-form" onSubmit={submit}>
        <div className="auth-form-top"><button className="auth-back" type="button" onClick={() => go("/")}>← Back to CareerForge</button><Brand onClick={() => go("/")} /></div>
        <div className="auth-form-intro"><p className="form-label">{register ? "Student registration" : admin ? "Administrator sign in" : "Student sign in"}</p><h2>{register ? "Create your workspace" : "Welcome back"}</h2><p>{register ? "A few details now, then you can begin building your career space." : "Use your account details to continue where you left off."}</p></div>
        {register && <label>Full name<input value={name} onChange={(e) => setName(e.target.value)} required /></label>}
        <label>Email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required placeholder="you@example.com" /></label>
        <label>Password<input type="password" minLength="8" value={password} onChange={(e) => setPassword(e.target.value)} required placeholder="At least 8 characters" /></label>
        {message && <p className="form-error">{message}</p>}
        <Button type="submit" disabled={submitting}>{submitting ? "Please wait..." : register ? "Create workspace" : "Continue"}<ArrowRight size={16} /></Button>
        <div className="auth-switch">{register ? <button className="text-button" type="button" onClick={() => go("/login/student")}>Already have an account? Sign in</button> : <><button className="text-button" type="button" onClick={() => go(admin ? "/login/student" : "/login/admin")}>Switch to {admin ? "student" : "administrator"} sign in</button>{!admin && <button className="text-button" type="button" onClick={() => go("/register")}>New student? Create an account</button>}</>}</div>
      </form>
      <aside className="auth-panel">
        <img className="auth-photo" src={authPhoto} alt={authPhotoAlt} />
        <div className="auth-photo-wash" aria-hidden="true" />
        <div className="auth-panel-inner"><div className="auth-panel-copy"><p className="auth-panel-eyebrow">{authView.eyebrow}</p><h1>{authView.title}</h1><p>{authView.copy}</p></div></div>
      </aside>
    </section>
  </main>;
}

function StudentProfile() {
  const current = getSession(); const [profile, setProfile] = useState(blankProfile); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false); const [uploadingPhoto, setUploadingPhoto] = useState(false); const [loading, setLoading] = useState(true);
  useEffect(() => { if (!current?.id) { setNotice("Please sign in again."); setLoading(false); return; } fetch(`${API_BASE_URL}/profiles/${current.id}`, { headers: { "X-User-Id": current.id } }).then(responseBody).then((body) => setProfile({ ...blankProfile, ...body, profilePhotoUrl: body.profilePhotoUrl?.startsWith("/") ? `${API_BASE_URL}${body.profilePhotoUrl}` : body.profilePhotoUrl, graduationYear: body.graduationYear || "", experienceYears: body.experienceYears ?? "" })).catch((e) => setNotice(e.message)).finally(() => setLoading(false)); }, []);
  const change = (event) => setProfile({ ...profile, [event.target.name]: event.target.value });
  const completedFields = [profile.university, profile.degree, profile.graduationYear, profile.experienceYears, profile.targetRole, profile.location, profile.skills, profile.hobbies, profile.bio].filter((value) => typeof value === "string" ? value.trim() : value !== null && value !== undefined).length; const completion = Math.round((completedFields / 9) * 100);
  useEffect(() => { if (loading) return undefined; const avatar = document.querySelector(".profile-avatar-preview"); if (!avatar || avatar.querySelector(".avatar-photo-picker")) return undefined; const picker = document.createElement("input"); picker.className = "avatar-photo-picker"; picker.type = "file"; picker.accept = "image/png,image/jpeg,image/webp"; picker.disabled = uploadingPhoto; picker.setAttribute("aria-label", uploadingPhoto ? "Profile photo is uploading" : profile.profilePhotoUrl ? "Change profile photo" : "Add profile photo"); picker.addEventListener("change", uploadPhoto); const openPicker = () => { if (!uploadingPhoto) picker.click(); }; const hint = document.createElement("span"); hint.className = "avatar-photo-hint"; hint.textContent = uploadingPhoto ? "Uploading" : profile.profilePhotoUrl ? "Change" : "Add"; avatar.appendChild(picker); avatar.appendChild(hint); avatar.addEventListener("click", openPicker); return () => { avatar.removeEventListener("click", openPicker); picker.remove(); hint.remove(); }; }, [loading, profile.profilePhotoUrl, uploadingPhoto]);
  async function uploadPhoto(event) { const photo = event.target.files?.[0]; if (!photo || uploadingPhoto) return; setUploadingPhoto(true); setNotice(""); try { const form = new FormData(); form.append("photo", photo); const response = await fetch(`${API_BASE_URL}/profiles/${current.id}/photo`, { method: "POST", headers: { "X-User-Id": current.id }, body: form }); const body = await responseBody(response); setProfile({ ...blankProfile, ...body, profilePhotoUrl: body.profilePhotoUrl?.startsWith("/") ? `${API_BASE_URL}${body.profilePhotoUrl}` : body.profilePhotoUrl, graduationYear: body.graduationYear || "", experienceYears: body.experienceYears ?? "" }); setNotice("Profile photo uploaded successfully."); } catch (e) { setNotice(e.message); } finally { event.target.value = ""; setUploadingPhoto(false); } }
  async function save(event) { event.preventDefault(); if (uploadingPhoto) return setNotice("Wait for the profile photo upload to finish before saving."); setSaving(true); setNotice(""); try { const response = await fetch(`${API_BASE_URL}/profiles/${current.id}`, { method: "PUT", headers: { "Content-Type": "application/json", "X-User-Id": current.id }, body: JSON.stringify({ ...profile, profilePhotoUrl: profile.profilePhotoUrl?.startsWith(`${API_BASE_URL}/profiles/`) ? `/profiles/${current.id}/photo` : profile.profilePhotoUrl, graduationYear: profile.graduationYear ? Number(profile.graduationYear) : null, experienceYears: profile.experienceYears === "" || profile.experienceYears == null ? null : Number(profile.experienceYears) }) }); const body = await responseBody(response); setProfile({ ...blankProfile, ...body, profilePhotoUrl: body.profilePhotoUrl?.startsWith("/") ? `${API_BASE_URL}${body.profilePhotoUrl}` : body.profilePhotoUrl, graduationYear: body.graduationYear || "", experienceYears: body.experienceYears ?? "" }); setNotice("Profile saved successfully."); } catch (e) { setNotice(e.message); } finally { setSaving(false); } }
  return <section className="profile-page"><header className="profile-hero"><div className="profile-identity"><div className="profile-avatar-preview">{profile.profilePhotoUrl ? <img src={profile.profilePhotoUrl} alt="Profile preview" /> : current?.name?.slice(0, 1)?.toUpperCase() || "S"}</div><div><h2>{current?.name || "Build your professional profile"}</h2><p>Give employers a clear picture of your education, direction, and strengths.</p></div></div><div className="profile-completion"><div><b>{loading ? "—" : `${completion}%`}</b><span>profile complete</span></div><i><em style={{ width: `${completion}%` }} /></i><small>{completedFields} of 9 profile details added</small></div></header><form className="data-form profile-form" onSubmit={save}><div className="profile-account-card"><div><span><b>{current?.name || "Your account"}</b><small>Account name</small></span><span><b>{current?.email || "Sign in to load email"}</b><small>Email address</small></span></div><p><ShieldCheck size={16} /> Your profile is private to your CareerForge workspace.</p></div><section className="profile-field-section"><div className="profile-section-title"><span>01</span><div><h3>Academic background</h3><p>Share the study details that frame your current stage.</p></div></div><div className="form-grid"><label>University<input name="university" value={profile.university || ""} onChange={change} placeholder="United International University" /></label><label>Degree / programme<input name="degree" value={profile.degree || ""} onChange={change} placeholder="BSc in Computer Science" /></label><label>Graduation year<input name="graduationYear" value={profile.graduationYear || ""} onChange={change} type="number" min="2000" max="2100" placeholder="2027" /></label><label>Experience (years)<input name="experienceYears" value={profile.experienceYears ?? ""} onChange={change} type="number" min="0" max="60" placeholder="0" /></label></div></section><section className="profile-field-section"><div className="profile-section-title"><span>02</span><div><h3>Career direction</h3><p>Use a target role and location to keep your job search focused.</p></div></div><div className="form-grid"><label>Target role<input name="targetRole" value={profile.targetRole || ""} onChange={change} placeholder="Junior Software Engineer" /></label><label>Location<input name="location" value={profile.location || ""} onChange={change} placeholder="Dhaka, Bangladesh" /></label><label>Profile photo URL <small>(optional)</small><input name="profilePhotoUrl" value={profile.profilePhotoUrl || ""} onChange={change} placeholder="https://..." /></label></div></section><section className="profile-field-section"><div className="profile-section-title"><span>03</span><div><h3>Skills &amp; interests</h3><p>Add the strengths and interests you want employers to see at a glance.</p></div></div><div className="form-grid profile-details-grid"><label>Skills <small>Separate skills with commas</small><textarea name="skills" value={profile.skills || ""} onChange={change} rows="3" placeholder="Java, React, MySQL, Figma" /></label><label>Hobbies &amp; interests <small>What do you enjoy beyond coursework?</small><textarea name="hobbies" value={profile.hobbies || ""} onChange={change} rows="3" placeholder="Photography, volunteering, chess" /></label></div></section><section className="profile-field-section bio-section"><div className="profile-section-title"><span>04</span><div><h3>Professional summary</h3><p>In 2–4 sentences, mention your interests, projects, strengths, and direction.</p></div></div><label className="full-field">Short professional bio<textarea name="bio" value={profile.bio || ""} onChange={change} rows="5" maxLength="500" placeholder="For example: Computer Science student interested in frontend engineering. Built projects with React and Spring Boot, and looking for an internship where I can grow..." /></label><small className="bio-count">{(profile.bio || "").length}/500 characters</small></section>{notice && <p className={notice.includes("success") ? "form-success" : "form-error"}>{notice}</p>}<footer className="profile-save-row"><div><b>Ready to save?</b><small>Your dashboard updates from these details.</small></div><Button type="submit" disabled={saving || loading}><Save size={15} />{saving ? "Saving..." : loading ? "Loading..." : "Save profile"}</Button></footer></form></section>;
}

function CareerVault() {
  const current = getSession(); const [resumes, setResumes] = useState([]); const [documents, setDocuments] = useState([]); const [resumeId, setResumeId] = useState(null); const [title, setTitle] = useState("My professional CV"); const [content, setContent] = useState({ ...blankResumeContent, fullName: current?.name || "", email: current?.email || "" }); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const load = () => { if (!current?.id) return setNotice("Please sign in again."); Promise.all([fetch(`${API_BASE_URL}/vault/resumes`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/vault/documents`, { headers }).then(responseBody)]).then(([resumeItems, documentItems]) => { setResumes(resumeItems); setDocuments(documentItems); }).catch((e) => setNotice(e.message)); };
  useEffect(() => { load(); }, []);
  function editResume(resume) { setResumeId(resume.id); setTitle(resume.title); setContent({ ...blankResumeContent, ...resume.content }); setNotice(""); }
  function newResume() { setResumeId(null); setTitle("My professional CV"); setContent({ ...blankResumeContent, fullName: current?.name || "", email: current?.email || "" }); setNotice(""); }
  const change = (event) => setContent({ ...content, [event.target.name]: event.target.value });
  async function saveResume(event) { event.preventDefault(); setSaving(true); setNotice(""); try { const response = await fetch(`${API_BASE_URL}/vault/resumes${resumeId ? `/${resumeId}` : ""}`, { method: resumeId ? "PUT" : "POST", headers, body: JSON.stringify({ title, content, isDefault: resumes.length === 0 }) }); const saved = await responseBody(response); setResumeId(saved.id); setNotice("Resume version saved."); load(); } catch (e) { setNotice(e.message); } finally { setSaving(false); } }
  async function makeDefault(id) { try { await responseBody(await fetch(`${API_BASE_URL}/vault/resumes/${id}/default`, { method: "PUT", headers })); setNotice("Default CV updated."); load(); } catch (e) { setNotice(e.message); } }
  async function removeResume(id) { if (!window.confirm("Delete this resume version?")) return; try { await responseBody(await fetch(`${API_BASE_URL}/vault/resumes/${id}`, { method: "DELETE", headers })); if (resumeId === id) newResume(); setNotice("Resume version deleted."); load(); } catch (e) { setNotice(e.message); } }
  async function upload(event) { const file = event.target.files?.[0]; if (!file) return; setNotice(""); const form = new FormData(); form.append("file", file); try { await responseBody(await fetch(`${API_BASE_URL}/vault/documents`, { method: "POST", headers: { "X-User-Id": current.id }, body: form })); setNotice("Document uploaded."); event.target.value = ""; load(); } catch (e) { setNotice(e.message); } }
  async function download(document) { try { const response = await fetch(`${API_BASE_URL}/vault/documents/${document.id}/download`, { headers: { "X-User-Id": current.id } }); if (!response.ok) throw new Error("Unable to download this document."); const url = URL.createObjectURL(await response.blob()); const link = window.document.createElement("a"); link.href = url; link.download = document.fileName; link.click(); URL.revokeObjectURL(url); } catch (e) { setNotice(e.message); } }
  async function removeDocument(id) { if (!window.confirm("Delete this uploaded document?")) return; try { await responseBody(await fetch(`${API_BASE_URL}/vault/documents/${id}`, { method: "DELETE", headers })); setNotice("Document deleted."); load(); } catch (e) { setNotice(e.message); } }
  function importPrevious() { try { const key = Object.keys(localStorage).find((item) => item.startsWith("careerforge_cv_")); if (!key) throw new Error("No previous CV Maker data was found in this browser."); const old = JSON.parse(localStorage.getItem(key)); setContent({ ...blankResumeContent, fullName: old.name || current?.name || "", email: old.email || current?.email || "", phone: old.phone || "", location: old.location || "", headline: old.title || "", summary: old.summary || "", skills: old.skills || "", education: Array.isArray(old.education) ? old.education.map((item) => typeof item === "string" ? item : `${item.school || item.institution || ""} ${item.degree || ""}`.trim()).join("\n") : old.education || "", experience: Array.isArray(old.experiences) ? old.experiences.map((item) => typeof item === "string" ? item : `${item.role || item.title || ""} ${item.company || ""}`.trim()).join("\n") : old.experience || "", projects: Array.isArray(old.projects) ? old.projects.map((item) => typeof item === "string" ? item : `${item.name || item.title || ""} ${item.description || ""}`.trim()).join("\n") : old.projects || "" }); setTitle(old.title ? `${old.title} CV` : "Imported CV"); setResumeId(null); setNotice("Previous CV Maker data imported. Review it and save a new version."); } catch (e) { setNotice(e.message); } }
  async function importJson(event) { const file = event.target.files?.[0]; if (!file) return; try { const old = JSON.parse(await file.text()); setContent({ ...blankResumeContent, ...old }); setTitle(old.title || "Imported CV"); setResumeId(null); setNotice("CV JSON imported. Review it and save a new version."); } catch { setNotice("That file is not valid CV JSON data."); } finally { event.target.value = ""; } }
  return <section className="vault-page"><div className="content-intro compact"><div><p className="eyebrow"><FileText size={14} /> Career Vault</p><h2>Build, keep, and select your CV.</h2><p>Create tailored CV versions or upload an existing PDF, DOC, or DOCX from your PC. Your selected CV is used when you apply for a job.</p></div><div className="vault-import"><Button className="quiet" type="button" onClick={importPrevious}>Import previous CV</Button><label className="import-file">Import CV JSON<input type="file" accept="application/json,.json" onChange={importJson} /></label></div></div>{notice && <p className={/(saved|updated|uploaded|deleted|imported)/.test(notice) ? "form-success" : "form-error"}>{notice}</p>}<div className="vault-layout"><div className="vault-editor"><form className="data-form" onSubmit={saveResume}><div className="form-row-title"><h3>{resumeId ? "Edit resume version" : "Create a resume version"}</h3><button type="button" className="text-button" onClick={newResume}>New version</button></div><label>Version name<input value={title} onChange={(e) => setTitle(e.target.value)} required placeholder="Software Engineer CV" /></label><div className="form-grid"><label>Full name<input name="fullName" value={content.fullName} onChange={change} /></label><label>Email<input name="email" type="email" value={content.email} onChange={change} /></label><label>Phone<input name="phone" value={content.phone} onChange={change} placeholder="01XXXXXXXXX" /></label><label>Location<input name="location" value={content.location} onChange={change} placeholder="Dhaka, Bangladesh" /></label><label className="full-field">Professional headline<input name="headline" value={content.headline} onChange={change} placeholder="Junior Software Engineer" /></label></div><label className="full-field">Professional summary<textarea name="summary" rows="4" value={content.summary} onChange={change} /></label><label className="full-field">Skills <small>(comma separated)</small><textarea name="skills" rows="2" value={content.skills} onChange={change} placeholder="Java, Spring Boot, MySQL" /></label><label className="full-field">Education <small>(one item per line)</small><textarea name="education" rows="3" value={content.education} onChange={change} placeholder="BSc in CSE — United International University" /></label><label className="full-field">Experience <small>(one item per line)</small><textarea name="experience" rows="3" value={content.experience} onChange={change} placeholder="Intern — Company, 2026" /></label><label className="full-field">Projects <small>(one item per line)</small><textarea name="projects" rows="3" value={content.projects} onChange={change} placeholder="CareerForge — Spring Boot and React project" /></label><Button type="submit" disabled={saving}><Save size={15} />{saving ? "Saving..." : "Save resume version"}</Button><Button className="quiet print-button" type="button" onClick={() => window.print()}>Print / Save as PDF</Button></form></div><aside className="cv-preview"><p className="eyebrow">Live preview</p><h2>{content.fullName || "Your name"}</h2><h3>{content.headline || "Professional headline"}</h3><p>{[content.email, content.phone, content.location].filter(Boolean).join(" · ")}</p>{content.summary && <section><b>Profile</b><p>{content.summary}</p></section>}{content.skills && <section><b>Skills</b><p>{content.skills}</p></section>}{content.education && <section><b>Education</b><p className="lines">{content.education}</p></section>}{content.experience && <section><b>Experience</b><p className="lines">{content.experience}</p></section>}{content.projects && <section><b>Projects</b><p className="lines">{content.projects}</p></section>}</aside></div><section className="vault-assets"><div className="content-card"><div className="list-heading"><h3>Saved resume versions</h3><span>{resumes.length} total</span></div>{resumes.length ? resumes.map((resume) => <article className="vault-row" key={resume.id}><div><b>{resume.title}</b><small>{resume.isDefault ? "Default CV" : "Resume version"}</small></div><div className="vault-actions"><button onClick={() => editResume(resume)}>Edit</button>{!resume.isDefault && <button onClick={() => makeDefault(resume.id)}><Star size={14} /> Set default</button>}<button className="danger" onClick={() => removeResume(resume.id)}><Trash2 size={14} /></button></div></article>) : <p className="muted">No resume version saved yet.</p>}</div><div className="content-card"><div className="list-heading"><h3>Uploaded CVs and documents</h3><label className="upload-button"><Upload size={14} /> Upload file<input type="file" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={upload} /></label></div><p className="upload-help">PDF, DOC, or DOCX · maximum 5 MB · stored locally in this project.</p>{documents.length ? documents.map((document) => <article className="vault-row" key={document.id}><div><b>{document.fileName}</b><small>{Math.ceil(document.fileSizeBytes / 1024)} KB · {document.contentType}</small></div><div className="vault-actions"><button onClick={() => download(document)}><Download size={14} /> Download</button><button className="danger" onClick={() => removeDocument(document.id)}><Trash2 size={14} /></button></div></article>) : <p className="muted">No CV or document uploaded yet.</p>}</div></section></section>;
}

function LegacyLearningPaths() {
  const current = getSession(); const [paths, setPaths] = useState([]); const [topic, setTopic] = useState(""); const [pathType, setPathType] = useState("skill"); const [levelCount, setLevelCount] = useState(10); const [notice, setNotice] = useState(""); const [creating, setCreating] = useState(false); const [recommending, setRecommending] = useState(false); const [activeId, setActiveId] = useState(null); const [quiz, setQuiz] = useState(null); const [answers, setAnswers] = useState([]); const [result, setResult] = useState(null); const [loadingLevel, setLoadingLevel] = useState(false);
  const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const load = async () => { if (!current?.id) return setNotice("Please sign in again."); try { const items = await responseBody(await fetch(`${API_BASE_URL}/learning-paths`, { headers })); setPaths(items); setActiveId((id) => id || items[0]?.id || null); } catch (error) { setNotice(error.message); } };
  useEffect(() => { load(); }, []);
  useEffect(() => { if (result) window.scrollTo(0, 0); }, [result]);
  const active = paths.find((item) => item.id === activeId) || null;
  async function recommendation() { if (!topic.trim()) return setNotice(`Enter a ${pathType === "skill" ? "skill" : "job role"} first.`); setRecommending(true); setNotice(""); try { const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/recommendation`, { method: "POST", headers, body: JSON.stringify({ topic: topic.trim(), pathType }) })); setLevelCount(item.recommendedLevels); setNotice(`Gemini recommends ${item.recommendedLevels} levels. ${item.reason}`); } catch (error) { setNotice(error.message); } finally { setRecommending(false); } }
  async function create(event) { event.preventDefault(); setCreating(true); setNotice(""); try { const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths`, { method: "POST", headers, body: JSON.stringify({ topic: topic.trim(), pathType, levelCount: Number(levelCount) }) })); setPaths((items) => [item, ...items]); setActiveId(item.id); setTopic(""); setQuiz(null); setResult(null); setNotice("Learning path created. Level 1 is ready when you are."); } catch (error) { setNotice(error.message); } finally { setCreating(false); } }
  async function deletePath(path) { if (!window.confirm(`Delete the ${path.topic} learning path and all of its progress?`)) return; setNotice(""); try { await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${path.id}`, { method: "DELETE", headers })); const remaining = paths.filter((item) => item.id !== path.id); setPaths(remaining); setActiveId(remaining[0]?.id || null); setQuiz(null); setResult(null); setNotice("Learning path deleted."); } catch (error) { setNotice(error.message); } }
  async function openLevel(number) { if (!active) return; setLoadingLevel(true); setNotice(""); setResult(null); try { const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${active.id}/levels/${number}`, { headers })); setQuiz(item); setAnswers(Array(item.questions.length).fill(null)); } catch (error) { setNotice(error.message); } finally { setLoadingLevel(false); } }
  async function submit(event) { event.preventDefault(); if (!quiz || answers.some((answer) => answer === null)) return setNotice("Choose an answer for every question before submitting."); setLoadingLevel(true); try { const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${active.id}/levels/${quiz.levelNumber}/attempts`, { method: "POST", headers, body: JSON.stringify({ answers }) })); setResult(item); setQuiz(null); await load(); } catch (error) { setNotice(error.message); } finally { setLoadingLevel(false); } }
  return <section className="learning-page"><div className="content-intro learning-intro"><div><p className="eyebrow"><Sparkles size={14} /> Gemini-powered practice</p><h2>Build a skill, one level at a time.</h2><p>Choose a skill or job role, set up to 50 levels, and pass each level with 70% before the next challenge unlocks.</p></div><span className="learning-score">70%<small>to pass</small></span></div><div className="learning-layout"><form className="data-form learning-builder" onSubmit={create}><div className="form-row-title"><h3>Create a learning path</h3><span>1–50 levels</span></div><div className="learning-type"><button type="button" className={pathType === "skill" ? "selected" : ""} onClick={() => setPathType("skill")}>Learn a skill</button><button type="button" className={pathType === "job" ? "selected" : ""} onClick={() => setPathType("job")}>Prepare for a job</button></div><label>{pathType === "skill" ? "Skill" : "Job role"}<input value={topic} onChange={(event) => setTopic(event.target.value)} placeholder={pathType === "skill" ? "e.g. Java, React, UI/UX" : "e.g. Junior Software Engineer"} required /></label><div className="level-picker"><div><b>{levelCount} levels</b><small>Level 1 starts unlocked. Every level after that needs a 70% pass.</small></div><input type="range" min="1" max="50" value={levelCount} onChange={(event) => setLevelCount(event.target.value)} /><output>{levelCount}</output></div><Button className="quiet" type="button" onClick={recommendation} disabled={recommending}>{recommending ? "Asking Gemini..." : "Ask Gemini to recommend levels"}<Sparkles size={14} /></Button><Button type="submit" disabled={creating}>{creating ? "Creating path..." : "Create learning path"}<ArrowRight size={15} /></Button></form><aside className="learning-guide"><p className="eyebrow">How it works</p><ol><li><b>01</b><span>Choose one focused skill or a job target.</span></li><li><b>02</b><span>Gemini generates five questions only when a level unlocks.</span></li><li><b>03</b><span>Score 70% or above to open the next level.</span></li></ol></aside></div>{notice && <p className={/(created|recommends|ready|deleted)/.test(notice) ? "form-success" : "form-error"}>{notice}</p>}{result && <div className="result-modal-backdrop" role="presentation"><section className={`result-modal ${result.passed ? "passed" : "retry"}`} role="dialog" aria-modal="true" aria-labelledby="level-result-title"><header><div><p className="eyebrow">Level result</p><h3 id="level-result-title">{result.passed ? "Level passed!" : "Review and try again"}</h3></div><button type="button" className="result-close" onClick={() => setResult(null)} aria-label="Close results">×</button></header><div className="result-score"><strong>{result.percentage}%</strong><span>{result.correctAnswers} of {result.totalQuestions} correct</span></div><p className="result-message">{result.message}</p><div className="answer-review">{result.results?.map((item) => <article className={item.correct ? "correct" : "wrong"} key={item.number}><b>{item.correct ? "✓ Correct" : "× Incorrect"} · Question {item.number}</b><p>{item.prompt}</p><small>Your answer: <strong>{item.selectedAnswer}</strong></small>{!item.correct && <small>Correct answer: <strong>{item.correctAnswer}</strong></small>}<em>{item.explanation}</em></article>)}</div><Button type="button" onClick={() => setResult(null)}>{result.passed ? "Continue" : "Try this level again"}</Button></section></div>}{result && <section className={`learning-result ${result.passed ? "passed" : "retry"}`}><b>{result.passed ? "Level passed!" : "Keep practising"}</b><strong>{result.percentage}%</strong><p>{result.correctAnswers} of {result.totalQuestions} correct · {result.message}</p></section>}<section className="learning-paths"><div className="list-heading"><h3>Your learning paths</h3><span>{paths.length} active</span></div>{paths.length ? <div className="path-tabs">{paths.map((path) => <article className={`path-tab${path.id === activeId ? " active" : ""}`} key={path.id}><button onClick={() => { setActiveId(path.id); setQuiz(null); setResult(null); }}><small>{path.pathType === "job" ? "JOB TARGET" : "SKILL"}</small><b>{path.topic}</b><span>Level {Math.min(path.nextUnlockedLevel, path.levelCount)} of {path.levelCount}</span></button><button className="path-delete" type="button" onClick={() => deletePath(path)} aria-label={`Delete ${path.topic} learning path`} title="Delete learning path"><Trash2 size={14} /></button></article>)}</div> : <p className="muted">Create your first personalised path to begin.</p>}{active && !quiz && <div className="level-grid">{active.levels.map((level) => <button key={level.number} className={`learning-level ${level.status}`} disabled={level.status === "locked" || loadingLevel} onClick={() => openLevel(level.number)}><span>{level.status === "completed" ? "✓" : level.status === "locked" ? "🔒" : level.number}</span><b>Level {level.number}</b><small>{level.status === "completed" ? `${level.bestScore}% best` : level.status === "available" ? "Start challenge" : "Pass previous level"}</small></button>)}</div>}{quiz && <form className="quiz-card" onSubmit={submit}><header><button type="button" className="text-button" onClick={() => setQuiz(null)}>← Back to levels</button><p className="eyebrow">Level {quiz.levelNumber}</p><h3>{quiz.title}</h3><p>{quiz.summary}</p></header>{quiz.questions.map((question) => <fieldset key={question.index}><legend>{question.index + 1}. {question.prompt}</legend>{question.options.map((option, optionIndex) => <label key={option}><input type="radio" name={`question-${question.index}`} checked={answers[question.index] === optionIndex} onChange={() => setAnswers((currentAnswers) => currentAnswers.map((answer, index) => index === question.index ? optionIndex : answer))} />{option}</label>)}</fieldset>)}<Button type="submit" disabled={loadingLevel}>{loadingLevel ? "Checking your answers..." : "Submit level"}<ClipboardCheck size={15} /></Button></form>}</section></section>;
}

function LearningPaths() {
  const current = getSession();
  const [paths, setPaths] = useState([]);
  const [topic, setTopic] = useState("");
  const [pathType, setPathType] = useState("skill");
  const [levelCount, setLevelCount] = useState(10);
  const [notice, setNotice] = useState("");
  const [creating, setCreating] = useState(false);
  const [recommending, setRecommending] = useState(false);
  const [activeId, setActiveId] = useState(null);
  const [quiz, setQuiz] = useState(null);
  const [answers, setAnswers] = useState([]);
  const [result, setResult] = useState(null);
  const [loadingLevel, setLoadingLevel] = useState(false);
  const [composerOpen, setComposerOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deletingPath, setDeletingPath] = useState(false);
  const [timeLeft, setTimeLeft] = useState(null);
  const [timerExpired, setTimerExpired] = useState(false);
  const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };

  const load = async () => {
    if (!current?.id) return setNotice("Please sign in again.");
    try {
      const items = await responseBody(await fetch(`${API_BASE_URL}/learning-paths`, { headers }));
      setPaths(items);
      setActiveId((id) => id || items[0]?.id || null);
    } catch (error) { setNotice(error.message); }
  };

  useEffect(() => { load(); }, []);
  useEffect(() => {
    if (!notice) return undefined;
    const dismiss = window.setTimeout(() => setNotice(""), 5000);
    return () => window.clearTimeout(dismiss);
  }, [notice]);
  useEffect(() => { if (result) window.scrollTo({ top: 0, behavior: "smooth" }); }, [result]);
  useEffect(() => {
    if (!deleteTarget) return undefined;
    const handleEscape = (event) => {
      if (event.key === "Escape" && !deletingPath) setDeleteTarget(null);
    };
    window.addEventListener("keydown", handleEscape);
    return () => window.removeEventListener("keydown", handleEscape);
  }, [deleteTarget, deletingPath]);
  useEffect(() => {
    if (!quiz) { setTimeLeft(null); setTimerExpired(false); return undefined; }
    setTimeLeft(Math.max(60, quiz.questions.length * 36));
    setTimerExpired(false);
    window.scrollTo(0, 0);
    const timer = window.setInterval(() => setTimeLeft((seconds) => seconds === null || seconds <= 0 ? 0 : seconds - 1), 1000);
    return () => window.clearInterval(timer);
  }, [quiz]);

  const active = paths.find((item) => item.id === activeId) || null;
  const completed = active?.levels.filter((level) => level.status === "completed") || [];
  const nextLevel = active?.levels.find((level) => level.status === "available") || null;
  const progress = active ? Math.round((completed.length / active.levelCount) * 100) : 0;
  const bestScore = completed.length ? Math.max(...completed.map((level) => level.bestScore || 0)) : 0;
  const timerText = timeLeft === null ? "" : `${String(Math.floor(timeLeft / 60)).padStart(2, "0")}:${String(timeLeft % 60).padStart(2, "0")}`;
  const timerUrgent = timeLeft !== null && timeLeft <= 60;

  async function recommendation() {
    if (!topic.trim()) return setNotice(`Enter a ${pathType === "skill" ? "skill" : "job role"} first.`);
    setRecommending(true); setNotice("");
    try {
      const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/recommendation`, { method: "POST", headers, body: JSON.stringify({ topic: topic.trim(), pathType }) }));
      setLevelCount(item.recommendedLevels);
      setNotice(`Gemini recommends ${item.recommendedLevels} levels. ${item.reason}`);
    } catch (error) { setNotice(error.message); } finally { setRecommending(false); }
  }

  async function create(event) {
    event.preventDefault(); setCreating(true); setNotice("");
    try {
      const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths`, { method: "POST", headers, body: JSON.stringify({ topic: topic.trim(), pathType, levelCount: Number(levelCount) }) }));
      setPaths((items) => [item, ...items]); setActiveId(item.id); setTopic(""); setQuiz(null); setResult(null); setComposerOpen(false);
      setNotice("Learning path created. Level 1 is ready when you are.");
    } catch (error) { setNotice(error.message); } finally { setCreating(false); }
  }

  async function deletePath() {
    const path = deleteTarget;
    if (!path || deletingPath) return;
    setDeletingPath(true);
    setNotice("");
    try {
      await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${path.id}`, { method: "DELETE", headers }));
      const remaining = paths.filter((item) => item.id !== path.id);
      setPaths(remaining); setActiveId(remaining[0]?.id || null); setQuiz(null); setResult(null);
      setDeleteTarget(null);
      setNotice("Learning path deleted.");
    } catch (error) { setNotice(error.message); } finally { setDeletingPath(false); }
  }

  async function openLevel(number) {
    if (!active) return;
    setLoadingLevel(true); setNotice(""); setResult(null);
    try {
      const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${active.id}/levels/${number}`, { headers }));
      setQuiz(item); setAnswers(Array(item.questions.length).fill(""));
    } catch (error) { setNotice(error.message); } finally { setLoadingLevel(false); }
  }

  async function regenerateQuestions() {
    if (!active || !quiz || !window.confirm("Generate a fresh question set for this level?")) return;
    setLoadingLevel(true); setNotice("");
    try {
      const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${active.id}/levels/${quiz.levelNumber}/regenerate`, { method: "POST", headers }));
      setQuiz(item); setAnswers(Array(item.questions.length).fill(""));
      setNotice("Fresh questions are ready.");
    } catch (error) { setNotice(error.message); } finally { setLoadingLevel(false); }
  }

  async function submit(event, timedOut = false) {
    event?.preventDefault();
    if (!quiz || (!timedOut && answers.some((answer) => !String(answer || "").trim()))) return setNotice("Answer every question before submitting.");
    setLoadingLevel(true);
    try {
      const submittedAnswers = timedOut ? answers.map((answer) => String(answer || "-1")) : answers;
      const item = await responseBody(await fetch(`${API_BASE_URL}/learning-paths/${active.id}/levels/${quiz.levelNumber}/attempts`, { method: "POST", headers, body: JSON.stringify({ answers: submittedAnswers }) }));
      setResult(item); setQuiz(null); await load();
    } catch (error) { setNotice(error.message); } finally { setLoadingLevel(false); }
  }

  useEffect(() => {
    if (timeLeft !== 0 || !quiz || loadingLevel || timerExpired) return;
    setTimerExpired(true);
    submit(null, true);
  }, [timeLeft, quiz, loadingLevel, timerExpired]);

  if (result) return <section className="assessment-result-page">
    <header className="assessment-result-head">
      <div><p className="eyebrow">Level result</p><h2>{result.passed ? "Level passed!" : "Review and try again"}</h2><p>{result.message}</p></div>
      <button type="button" className="assessment-back" onClick={() => setResult(null)}>← Back to assessments</button>
    </header>
    <section className={`assessment-result-summary ${result.passed ? "passed" : "retry"}`}>
      <div className="result-ring" style={{ "--result-progress": `${result.percentage * 3.6}deg` }}><strong>{result.percentage}%</strong><span>score</span></div>
      <div><p className="eyebrow">Your outcome</p><h3>{result.correctAnswers} of {result.totalQuestions} correct</h3><p>{result.passed ? "Great work — your next level is now unlocked." : "You need 70% to unlock the next level. Review the answers and come back stronger."}</p></div>
      <span className="result-status">{result.passed ? "Level unlocked" : "Try again"}</span>
    </section>
    <section className="answer-review-panel"><div className="review-panel-heading"><div><p className="eyebrow">Answer review</p><h3>Learn from this attempt</h3></div><span>{result.totalQuestions} questions</span></div><div className="answer-review">{result.results?.map((item) => <article className={item.correct ? "correct" : "wrong"} key={item.number}><div className="review-status">{item.correct ? "✓ Correct" : "× Needs review"}<span>Question {item.number}</span></div><p>{item.prompt}</p><small>Your answer: <strong>{item.selectedAnswer}</strong></small>{!item.correct && <small>Correct answer: <strong>{item.correctAnswer}</strong></small>}<em>{item.explanation}</em></article>)}</div><Button onClick={() => setResult(null)}>{result.passed ? "Continue journey" : "Try this level again"}<ArrowRight size={15} /></Button></section>
  </section>;

  if (quiz) return <section className="assessment-quiz-page">
    <form className="quiz-card" onSubmit={submit}>
      <header><div className="quiz-top-actions"><button type="button" className="assessment-back" onClick={() => setQuiz(null)}>← Back to levels</button><button type="button" className="refresh-questions" onClick={regenerateQuestions} disabled={loadingLevel}>↻ Generate new questions</button></div><p className="eyebrow">Level {quiz.levelNumber} assessment</p><h2>{quiz.title}</h2><p>{quiz.summary}</p><div className="quiz-format"><span>Mixed format</span><small>MCQ · Debugging · Scenario · Short answer</small></div><div className="quiz-progress"><span>Answer every question</span><b>{answers.filter((answer) => String(answer || "").trim()).length} / {quiz.questions.length} answered</b></div><div className={`quiz-timer${timerUrgent ? " urgent" : ""}`} aria-live="polite"><span>Time left</span><strong>{timerText}</strong><small>{quiz.questions.length} questions · {Math.ceil((quiz.questions.length * 36) / 60)} min limit</small></div></header>
      <div className="quiz-questions">{quiz.questions.map((question) => <section className={`quiz-question ${question.type?.toLowerCase() || "mcq"}`} key={question.index}><div className="question-type"><span>{question.type === "SHORT_ANSWER" ? "Short answer" : question.type === "DEBUGGING" ? "Debugging" : question.type === "SCENARIO" ? "Scenario" : "Multiple choice"}</span></div><p className="quiz-question-title"><span>{question.index + 1}</span>{question.prompt}</p>{question.codeSnippet && <pre className="question-code"><code>{question.codeSnippet}</code></pre>}{question.type === "SHORT_ANSWER" ? <div className="short-answer"><textarea value={answers[question.index] || ""} onChange={(event) => setAnswers((currentAnswers) => currentAnswers.map((answer, index) => index === question.index ? event.target.value : answer))} rows="5" maxLength="1000" placeholder="Write a concise answer in your own words..." /><small>{question.answerHint}</small></div> : <div>{(question.options || []).map((option, optionIndex) => <label key={option}><input type="radio" name={`question-${question.index}`} checked={answers[question.index] === String(optionIndex)} onChange={() => setAnswers((currentAnswers) => currentAnswers.map((answer, index) => index === question.index ? String(optionIndex) : answer))} /><i>{String.fromCharCode(65 + optionIndex)}</i><span>{option}</span></label>)}</div>}</section>)}</div>
      <footer><p>Pass mark <b>70%</b></p><Button type="submit" disabled={loadingLevel}>{loadingLevel ? "Checking your answers..." : "Submit assessment"}<ClipboardCheck size={15} /></Button></footer>
    </form>
  </section>;

  return <section className="assessment-dashboard">
    <section className="assessment-hero">
      <div className="assessment-hero-copy"><p className="eyebrow"><Sparkles size={14} /> Gemini-powered practice</p><h2>{active ? `${active.topic} learning journey` : "Build a skill, one level at a time."}</h2><p>{active ? `You have completed ${completed.length} of ${active.levelCount} levels. Keep the momentum going with the next focused challenge.` : "Create a focused learning path, then unlock each level by scoring 70% or above."}</p><div className="hero-actions">{nextLevel ? <Button type="button" onClick={() => openLevel(nextLevel.number)} disabled={loadingLevel}>{loadingLevel ? "Preparing questions..." : `Continue level ${nextLevel.number}`}<ArrowRight size={15} /></Button> : <Button type="button" onClick={() => setComposerOpen(true)}>Create a learning path <ArrowRight size={15} /></Button>}<button type="button" className="hero-link" onClick={() => setComposerOpen(true)}>+ New path</button></div></div>
      <div className="journey-visual"><div className="journey-ring" style={{ "--journey-progress": `${Math.max(progress, 4) * 3.6}deg` }}><div><strong>{progress}%</strong><span>complete</span></div></div><div className="journey-stats"><span><b>{active ? `Level ${nextLevel?.number || active.levelCount}` : "Ready"}</b><small>{active ? `of ${active.levelCount} levels` : "to start"}</small></span><span><b>{bestScore || "—"}{bestScore ? "%" : ""}</b><small>best score</small></span></div></div>
      <div className="journey-chart" aria-label="Learning progress chart"><div className="chart-heading"><span>Growth trend</span><b>{completed.length ? "+1 level" : "Start here"}</b></div><svg viewBox="0 0 250 88" role="img"><defs><linearGradient id="journeyFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#b8ef80" stopOpacity=".52"/><stop offset="1" stopColor="#b8ef80" stopOpacity="0"/></linearGradient></defs><path d="M0 73 C24 67, 35 69, 56 58 S89 64, 108 43 S143 53, 164 31 S201 40, 250 9 L250 88 L0 88 Z" fill="url(#journeyFill)"/><path d="M0 73 C24 67, 35 69, 56 58 S89 64, 108 43 S143 53, 164 31 S201 40, 250 9" fill="none" stroke="#b8ef80" strokeWidth="4" strokeLinecap="round"/><circle cx="164" cy="31" r="5" fill="#fff" stroke="#b8ef80" strokeWidth="3"/></svg><div className="chart-axis"><span>Start</span><span>Today</span></div></div>
    </section>

    {notice && <p className={/(created|recommends|ready|deleted)/.test(notice) ? "form-success" : "form-error"}>{notice}</p>}

    {deleteTarget && <div className="learning-delete-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget && !deletingPath) setDeleteTarget(null); }}><section className="learning-delete-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-learning-path-title" aria-describedby="delete-learning-path-warning"><header className="learning-delete-header"><div className="learning-delete-heading"><div className="learning-delete-icon"><Trash2 size={19} /></div><div><p className="eyebrow">Delete learning path</p><h3 id="delete-learning-path-title">Delete this learning path?</h3></div></div><button className="learning-delete-close" type="button" aria-label="Close delete confirmation" onClick={() => setDeleteTarget(null)} disabled={deletingPath}>×</button></header><div className="learning-delete-path"><span>Path to remove</span><strong>{deleteTarget.topic}</strong></div><div className="learning-delete-warning" id="delete-learning-path-warning"><b>This action cannot be undone.</b><p>All completed levels, scores, and assessment progress for this path will be permanently removed.</p></div><div className="learning-delete-actions"><button className="learning-delete-cancel" type="button" onClick={() => setDeleteTarget(null)} disabled={deletingPath} autoFocus>Cancel</button><button className="learning-delete-confirm" type="button" onClick={deletePath} disabled={deletingPath}><Trash2 size={15} />{deletingPath ? "Deleting..." : "Delete permanently"}</button></div></section></div>}

    {composerOpen && <section className="assessment-composer"><div className="composer-heading"><div><p className="eyebrow">New learning path</p><h3>Choose what you want to master</h3></div><button type="button" aria-label="Close learning path form" onClick={() => setComposerOpen(false)}>×</button></div><div className="learning-layout"><form className="data-form learning-builder" onSubmit={create}><div className="learning-type"><button type="button" className={pathType === "skill" ? "selected" : ""} onClick={() => setPathType("skill")}>Learn a skill</button><button type="button" className={pathType === "job" ? "selected" : ""} onClick={() => setPathType("job")}>Prepare for a job</button></div><label>{pathType === "skill" ? "Skill" : "Job role"}<input value={topic} onChange={(event) => setTopic(event.target.value)} placeholder={pathType === "skill" ? "e.g. Java, React, UI/UX" : "e.g. Junior Software Engineer"} required /></label><div className="level-picker"><div><b>{levelCount} levels</b><small>One level unlocks at a time. You need 70% to continue.</small></div><input type="range" min="1" max="50" value={levelCount} onChange={(event) => setLevelCount(event.target.value)} /><output>{levelCount}</output></div><div className="composer-actions"><Button className="quiet" type="button" onClick={recommendation} disabled={recommending}>{recommending ? "Asking Gemini..." : "Recommend levels"}<Sparkles size={14} /></Button><Button type="submit" disabled={creating}>{creating ? "Creating path..." : "Create path"}<ArrowRight size={15} /></Button></div></form><aside className="learning-guide"><p className="eyebrow">A focused rhythm</p><ol><li><b>01</b><span>Pick one skill or role that matters now.</span></li><li><b>02</b><span>Get five Gemini-generated questions per level.</span></li><li><b>03</b><span>Pass at 70% and keep moving forward.</span></li></ol></aside></div></section>}

    <section className="assessment-roadmap"><div className="roadmap-heading"><div><p className="eyebrow">Your roadmap</p><h3>{active ? active.topic : "No path selected"}</h3></div>{paths.length > 0 && <span>{paths.length} active {paths.length === 1 ? "path" : "paths"}</span>}</div>
      {paths.length ? <div className="path-tabs">{paths.map((path) => <article className={`path-tab${path.id === activeId ? " active" : ""}`} key={path.id}><button type="button" onClick={() => { setActiveId(path.id); setResult(null); }}><small>{path.pathType === "job" ? "JOB TARGET" : "SKILL"}</small><b>{path.topic}</b><span>Level {Math.min(path.nextUnlockedLevel, path.levelCount)} of {path.levelCount}</span></button><button className="path-delete" type="button" onClick={() => setDeleteTarget(path)} aria-label={`Delete ${path.topic} learning path`} title="Delete learning path"><Trash2 size={14} /></button></article>)}</div> : <div className="roadmap-empty"><span><Target size={20} /></span><div><b>Your first learning path is waiting.</b><p>Set a topic, choose your number of levels, and let Gemini prepare the practice.</p></div><Button type="button" onClick={() => setComposerOpen(true)}>Create path <ArrowRight size={14} /></Button></div>}
      {active && <div className="level-grid">{active.levels.map((level) => <button key={level.number} type="button" className={`learning-level ${level.status}`} disabled={level.status === "locked" || loadingLevel} onClick={() => openLevel(level.number)}><span>{level.status === "completed" ? "✓" : level.status === "locked" ? "🔒" : level.number}</span><b>Level {level.number}</b><small>{level.status === "completed" ? `${level.bestScore}% best score` : level.status === "available" ? loadingLevel ? "Generating questions..." : "Start challenge" : "Pass previous level"}</small>{level.status === "available" && <em>Current</em>}</button>)}</div>}
    </section>
  </section>;
}

function LegacyStudentJobs() {
  const current = getSession(); const [jobs, setJobs] = useState([]); const [applications, setApplications] = useState([]); const [resumes, setResumes] = useState([]); const [documents, setDocuments] = useState([]); const [selectedJob, setSelectedJob] = useState(null); const [selectedCv, setSelectedCv] = useState(""); const [notice, setNotice] = useState(""); const [submitting, setSubmitting] = useState(false);
  const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const load = () => { fetch(`${API_BASE_URL}/jobs`).then(responseBody).then(setJobs).catch((e) => setNotice(e.message)); if (current?.id) Promise.all([fetch(`${API_BASE_URL}/applications`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/vault/resumes`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/vault/documents`, { headers }).then(responseBody)]).then(([applicationItems, resumeItems, documentItems]) => { setApplications(applicationItems); setResumes(resumeItems); setDocuments(documentItems); const defaultResume = resumeItems.find((item) => item.isDefault); if (defaultResume) setSelectedCv((existing) => existing || `resume:${defaultResume.id}`); }).catch((e) => setNotice(e.message)); };
  useEffect(() => { load(); }, []);
  async function apply(event) { event.preventDefault(); if (!selectedJob || !selectedCv) return setNotice("Select a resume version or uploaded document first."); setSubmitting(true); setNotice(""); try { const [cvSourceType, cvSourceId] = selectedCv.split(":"); const response = await fetch(`${API_BASE_URL}/jobs/${selectedJob.id}/applications`, { method: "POST", headers, body: JSON.stringify({ cvSourceType, cvSourceId: Number(cvSourceId) }) }); const application = await responseBody(response); setApplications([application, ...applications]); setSelectedJob(null); setNotice("Application submitted successfully with your selected CV."); } catch (e) { setNotice(e.message); } finally { setSubmitting(false); } }
  return <section><div className="content-intro compact"><div><p className="eyebrow"><BriefcaseBusiness size={14} /> Live opportunities</p><h2>Jobs published by CareerForge.</h2><p>Choose a role, then select a Career Vault CV to submit with your application.</p></div></div>{selectedJob && <form className="apply-panel" onSubmit={apply}><div><p className="eyebrow"><FileText size={14} /> CV selection</p><h3>Apply for {selectedJob.title}</h3><p>{selectedJob.companyName} · Deadline {selectedJob.expiryDate}</p></div><label>Select the CV to submit<select value={selectedCv} onChange={(e) => setSelectedCv(e.target.value)} required><option value="">Choose a CV or document</option>{resumes.length > 0 && <optgroup label="Resume versions">{resumes.map((resume) => <option key={`resume:${resume.id}`} value={`resume:${resume.id}`}>{resume.title}{resume.isDefault ? " (default)" : ""}</option>)}</optgroup>}{documents.length > 0 && <optgroup label="Uploaded documents">{documents.map((document) => <option key={`document:${document.id}`} value={`document:${document.id}`}>{document.fileName}</option>)}</optgroup>}</select></label>{resumes.length === 0 && documents.length === 0 && <p className="form-error">Create a resume version or upload a CV in Career Vault before applying.</p>}<div className="row"><Button type="submit" disabled={submitting || !selectedCv}>{submitting ? "Submitting..." : "Submit selected CV"}<ArrowRight size={15} /></Button><Button className="quiet" type="button" onClick={() => setSelectedJob(null)}>Cancel</Button></div></form>}{notice && <p className={notice.includes("success") ? "form-success" : "form-error"}>{notice}</p>}<div className="job-card-grid">{jobs.length ? jobs.map((job) => { const application = applications.find((item) => item.jobId === job.id); return <article className="job-card" key={job.id}><div className="job-company"><span><Building2 size={18} /></span><div><small>{job.companyName}</small><h3>{job.title}</h3></div></div><p>{job.description}</p><div className="job-meta"><span><MapPin size={14} /> {job.location || "Location flexible"}</span><span>{job.workMode}</span><span>{job.employmentType.replace("_", " ")}</span></div><footer><span>Apply by {job.expiryDate}</span>{application ? <b className="application-state">{application.status}</b> : <Button type="button" onClick={() => { setSelectedJob(job); setNotice(""); }}>Select CV <ArrowRight size={14} /></Button>}</footer></article>; }) : <EmptyPanel title="No published jobs yet" copy="When an administrator publishes a job, it will appear here." />}</div>{applications.length > 0 && <section className="content-card application-list"><div className="list-heading"><h3>Your submitted applications</h3><span>{applications.length} total</span></div>{applications.map((application) => <article key={application.id}><div><b>{application.jobTitle}</b><small>{application.companyName} · {application.cvTitle} · Submitted {new Date(application.appliedAt).toLocaleDateString()}</small></div><span className="status submitted">{application.status}</span></article>)}</section>}</section>;
}

function JobMatchCards({ matches, applications, onSelect, showProfileMatch = true }) {
  return <div className="job-card-grid">{matches.map((match) => { const job = match.job; const breakdown = match.scoreBreakdown; const application = applications.find((item) => item.jobId === job.id); return <article className="job-card matched-job" key={job.id}><div className="job-company"><span><Building2 size={18} /></span><div><small>{job.companyName}</small><h3>{job.title}</h3></div>{showProfileMatch && <b className="match-score">{match.matchPercentage}% match</b>}</div><p>{job.description}</p>{showProfileMatch && match.matchedSkills?.length > 0 && <div className="matched-skills">{match.matchedSkills.map((skill) => <span key={skill}>{skill}</span>)}</div>}{showProfileMatch && <small className="match-summary">{match.matchSummary}</small>}{showProfileMatch && breakdown && <small className="match-breakdown">Role {breakdown.role}/40 · Experience {breakdown.experience}/25 · Skills {breakdown.skills}/20 · Location {breakdown.location}/10 · Freshness {breakdown.freshness}/5</small>}<div className="job-meta"><span><MapPin size={14} /> {job.location || "Location flexible"}</span><span>{job.workMode}</span><span>{job.employmentType.replace("_", " ")}</span></div><footer><span>Apply by {job.expiryDate}</span><div>{job.sourceUrl && <a className="job-source-link" href={job.sourceUrl} target="_blank" rel="noreferrer">View source</a>}{application ? <b className="application-state">{application.status}</b> : <Button type="button" onClick={() => onSelect(job)}>Select CV <ArrowRight size={14} /></Button>}</div></footer></article>; })}</div>;
}

function MatchPagination({ page, totalPages, onChange, label }) {
  if (totalPages <= 1) return null;
  const numbers = [...new Set([1, 2, 3, page - 1, page, page + 1, totalPages])].filter((number) => number >= 1 && number <= totalPages).sort((a, b) => a - b);
  const items = numbers.flatMap((number, index) => index > 0 && number - numbers[index - 1] > 1 ? [`ellipsis-${number}`, number] : [number]);
  return <nav className="job-pagination match-pagination" aria-label={label}><button type="button" disabled={page === 1} onClick={() => onChange(Math.max(1, page - 1))}>Previous</button>{items.map((item) => typeof item === "number" ? <button type="button" aria-label={`Go to page ${item}`} className={item === page ? "active" : ""} key={`${label}-${item}`} onClick={() => onChange(item)}>{item}</button> : <span className="page-ellipsis" aria-hidden="true" key={`${label}-${item}`}>…</span>)}<button type="button" disabled={page === totalPages} onClick={() => onChange(Math.min(totalPages, page + 1))}>Next</button><small>Page {page} of {totalPages}</small></nav>;
}

function StudentJobs() {
  const current = getSession();
  const [matches, setMatches] = useState([]);
  const [allMatches, setAllMatches] = useState([]);
  const [searchResults, setSearchResults] = useState([]);
  const [allSearchResults, setAllSearchResults] = useState([]);
  const [hasSearched, setHasSearched] = useState(false);
  const [recommendationPage, setRecommendationPage] = useState(1);
  const [searchPage, setSearchPage] = useState(1);
  const [applications, setApplications] = useState([]);
  const [resumes, setResumes] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [selectedJob, setSelectedJob] = useState(null);
  const [selectedCv, setSelectedCv] = useState("");
  const [notice, setNotice] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [refreshingMatches, setRefreshingMatches] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [filters, setFilters] = useState({ query: "", location: "", skills: "", workMode: "", employmentType: "" });
  const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };

  const load = async (activeFilters = filters, searchMode = false) => {
    if (!current?.id) { setLoading(false); setNotice("Please sign in again to view job matches."); return; }
    setLoading(true);
    try {
      const params = new URLSearchParams(Object.entries(activeFilters).filter(([, value]) => value));
      const [jobMatches, filteredMatches, applicationItems, resumeItems, documentItems] = await Promise.all([
        fetch(`${API_BASE_URL}/jobs/matches`, { headers }).then(responseBody),
        searchMode ? fetch(`${API_BASE_URL}/jobs/matches?${params}`, { headers }).then(responseBody) : Promise.resolve([]),
        fetch(`${API_BASE_URL}/applications`, { headers }).then(responseBody),
        fetch(`${API_BASE_URL}/vault/resumes`, { headers }).then(responseBody),
        fetch(`${API_BASE_URL}/vault/documents`, { headers }).then(responseBody),
      ]);
      setAllMatches(jobMatches); setMatches(jobMatches.slice(0, 10)); setRecommendationPage(1); if (searchMode) { setAllSearchResults(filteredMatches); setSearchResults(filteredMatches.slice(0, 10)); setSearchPage(1); } setApplications(applicationItems); setResumes(resumeItems); setDocuments(documentItems);
      setLastUpdated(new Date());
      const defaultResume = resumeItems.find((item) => item.isDefault);
      if (defaultResume) setSelectedCv((value) => value || `resume:${defaultResume.id}`);
    } catch (error) { setNotice(error.message); }
    finally { setLoading(false); }
  };
  useEffect(() => { load({}, false); const refresh = window.setInterval(() => load({}, false), 60 * 60 * 1000); return () => window.clearInterval(refresh); }, []);

  const changeFilter = (event) => setFilters({ ...filters, [event.target.name]: event.target.value });
  async function refreshRecommendations() { setRefreshingMatches(true); setNotice(""); try { await load({}, false); } finally { setRefreshingMatches(false); } }
  const search = (event) => { event.preventDefault(); setNotice(""); setHasSearched(true); setSearchResults([]); load(filters, true); };
  const clearFilters = () => { const empty = { query: "", location: "", skills: "", workMode: "", employmentType: "" }; setFilters(empty); setHasSearched(false); setSearchResults([]); setAllSearchResults([]); setNotice(""); load(empty, false); };
  const changeRecommendationPage = (page) => { setRecommendationPage(page); setMatches(allMatches.slice((page - 1) * 10, page * 10)); window.setTimeout(() => document.querySelector(".profile-match-heading")?.scrollIntoView({ behavior: "smooth", block: "start" }), 0); };
  const changeSearchPage = (page) => { setSearchPage(page); setSearchResults(allSearchResults.slice((page - 1) * 10, page * 10)); window.setTimeout(() => document.querySelector(".search-results-section")?.scrollIntoView({ behavior: "smooth", block: "start" }), 0); };
  async function apply(event) {
    event.preventDefault();
    if (!selectedJob || !selectedCv) return setNotice("Select a resume version or uploaded document first.");
    setSubmitting(true); setNotice("");
    try {
      const [cvSourceType, cvSourceId] = selectedCv.split(":");
      const application = await responseBody(await fetch(`${API_BASE_URL}/jobs/${selectedJob.id}/applications`, { method: "POST", headers, body: JSON.stringify({ cvSourceType, cvSourceId: Number(cvSourceId) }) }));
      setApplications([application, ...applications]); setSelectedJob(null); setNotice("Application submitted successfully with your selected CV.");
    } catch (error) { setNotice(error.message); }
    finally { setSubmitting(false); }
  }

  return <section className="student-jobs-page">
    <div className="content-intro compact"><div className="jobs-hero-copy"><h2>Find your next opportunity.</h2><p>Roles are ranked from your target role and skills. Search further by title, location, work mode, or type.</p></div><div className="jobs-hero-stats" aria-label="Your job search summary"><article><small>Profile matches</small><b>{loading ? "—" : allMatches.length}</b><span>ready to explore</span></article><article><small>Applications</small><b>{loading ? "—" : applications.length}</b><span>currently tracked</span></article></div></div>
    <form className="job-search-panel" onSubmit={search}>
      <label className="job-search-main"><Search size={17} /><input name="query" value={filters.query} onChange={changeFilter} placeholder="Search job title or company" /></label>
      <input name="location" value={filters.location} onChange={changeFilter} placeholder="Location" />
      <input name="skills" value={filters.skills} onChange={changeFilter} placeholder="Required skill, e.g. React" />
      <select name="workMode" value={filters.workMode} onChange={changeFilter}><option value="">Any work mode</option><option value="remote">Remote</option><option value="hybrid">Hybrid</option><option value="onsite">Onsite</option></select>
      <select name="employmentType" value={filters.employmentType} onChange={changeFilter}><option value="">Any job type</option><option value="internship">Internship</option><option value="part_time">Part time</option><option value="full_time">Full time</option><option value="contract">Contract</option></select>
      <Button type="submit"><Search size={15} /> Search</Button><button className="text-button" type="button" onClick={clearFilters}>Clear</button>
    </form>
    {hasSearched && <section className="content-card search-results-section"><div className="job-results-heading"><div><p className="eyebrow"><Search size={14} /> Search results</p><h3>{loading ? "Searching jobs..." : `${allSearchResults.length} jobs match your filters`}</h3><p>These listings are matched only against your search criteria—not your profile or CV.</p></div></div>{searchResults.length ? <JobMatchCards matches={searchResults} applications={applications} showProfileMatch={false} onSelect={(job) => { setSelectedJob(job); setNotice(""); }} /> : !loading && <EmptyPanel title="No jobs match these filters" copy="Try a broader title, location, skill, or job type." />}<MatchPagination page={searchPage} totalPages={Math.ceil(allSearchResults.length / 10)} onChange={changeSearchPage} label="Search results pagination" /></section>}
    {selectedJob && <form className="apply-panel" onSubmit={apply}><div><p className="eyebrow"><FileText size={14} /> CV selection</p><h3>Apply for {selectedJob.title}</h3><p>{selectedJob.companyName} · Deadline {selectedJob.expiryDate}</p></div><label>Select the CV to submit<select value={selectedCv} onChange={(event) => setSelectedCv(event.target.value)} required><option value="">Choose a CV or document</option>{resumes.length > 0 && <optgroup label="Resume versions">{resumes.map((resume) => <option key={`resume:${resume.id}`} value={`resume:${resume.id}`}>{resume.title}{resume.isDefault ? " (default)" : ""}</option>)}</optgroup>}{documents.length > 0 && <optgroup label="Uploaded documents">{documents.map((document) => <option key={`document:${document.id}`} value={`document:${document.id}`}>{document.fileName}</option>)}</optgroup>}</select></label>{resumes.length === 0 && documents.length === 0 && <p className="form-error">Create a resume version or upload a CV in Career Vault before applying.</p>}<div className="row"><Button type="submit" disabled={submitting || !selectedCv}>{submitting ? "Submitting..." : "Submit selected CV"}<ArrowRight size={15} /></Button><Button className="quiet" type="button" onClick={() => setSelectedJob(null)}>Cancel</Button></div></form>}
    {notice && <p className={notice.includes("success") ? "form-success" : "form-error"}>{notice}</p>}
    {!hasSearched && <><div className="job-results-heading profile-match-heading"><div><p className="eyebrow"><Sparkles size={14} /> Recommended for you</p><h3>{loading ? "Finding your matches..." : `${allMatches.length} profile-matched opportunities`}</h3><p>Ranked by your target role, skills, experience, location, and listing freshness. Showing 10 per page.</p></div><div className="job-refresh-control"><button className="job-refresh-button" type="button" onClick={refreshRecommendations} disabled={loading || refreshingMatches}><RefreshCw size={14} className={refreshingMatches ? "spin" : ""} />{refreshingMatches ? "Refreshing..." : "Refresh matches"}</button><small>{lastUpdated ? `Updated ${lastUpdated.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}` : "Updates every hour"}</small></div></div>
    <div className="job-card-grid">{matches.map((match) => { const job = match.job; const breakdown = match.scoreBreakdown; const application = applications.find((item) => item.jobId === job.id); return <article className="job-card matched-job" key={job.id}><div className="job-company"><span><Building2 size={18} /></span><div><small>{job.companyName}</small><h3>{job.title}</h3></div><b className="match-score">{match.matchPercentage}% match</b></div><p>{job.description}</p>{match.matchedSkills?.length > 0 && <div className="matched-skills">{match.matchedSkills.map((skill) => <span key={skill}>{skill}</span>)}</div>}<small className="match-summary">{match.matchSummary}</small>{breakdown && <small className="match-breakdown">Role {breakdown.role}/40 · Experience {breakdown.experience}/25 · Skills {breakdown.skills}/20 · Location {breakdown.location}/10 · Freshness {breakdown.freshness}/5</small>}<div className="job-meta"><span><MapPin size={14} /> {job.location || "Location flexible"}</span><span>{job.workMode}</span><span>{job.employmentType.replace("_", " ")}</span></div><footer><span>Apply by {job.expiryDate}</span><div>{job.sourceUrl && <a className="job-source-link" href={job.sourceUrl} target="_blank" rel="noreferrer">View source</a>}{application ? <b className="application-state">{application.status}</b> : <Button type="button" onClick={() => { setSelectedJob(job); setNotice(""); }}>Select CV <ArrowRight size={14} /></Button>}</div></footer></article>; })}</div>
    {allMatches.length > 0 && <div className="match-section-actions"><MatchPagination page={recommendationPage} totalPages={Math.ceil(allMatches.length / 10)} onChange={changeRecommendationPage} label="Profile recommendations pagination" /></div>}
    {!loading && matches.length === 0 && <EmptyPanel title="No matching jobs found" copy="Try a broader search, or add skills and a target role in My profile to improve recommendations." />}</>}
  </section>;
}

function AdminJobs() {
  const current = getSession(); const [jobs, setJobs] = useState([]); const [job, setJob] = useState(blankJob); const [editingId, setEditingId] = useState(null); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false); const [syncing, setSyncing] = useState(false); const [loadingJobs, setLoadingJobs] = useState(true); const [syncStatus, setSyncStatus] = useState(null); const [groupPages, setGroupPages] = useState({}); const [embeddingStatus, setEmbeddingStatus] = useState(null); const [embeddingBusy, setEmbeddingBusy] = useState(false);
  const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const load = () => { if (!current?.id) { setLoadingJobs(false); setNotice("Please sign in again as an administrator."); return; } setLoadingJobs(true); fetch(`${API_BASE_URL}/admin/jobs`, { headers }).then(responseBody).then((items) => { setJobs(items); setGroupPages({}); }).catch((e) => setNotice(e.message)).finally(() => setLoadingJobs(false)); };
  useEffect(() => { load(); if (current?.id) { fetch(`${API_BASE_URL}/admin/jobs/sync/status?source=bdjobs`, { headers }).then(responseBody).then((status) => { setSyncStatus(status); if (status.status === "success") setNotice(`BDJobs sync updated: ${status.newJobs ?? 0} new, ${status.publishedJobs ?? 0} published, ${status.needsReviewJobs ?? 0} flagged. Scheduler ${status.schedulerEnabled ? "enabled" : "manual only"}; interval ${Math.round((status.intervalMs || 0) / 3600000)}h.`); }).catch(() => {}); fetch(`${API_BASE_URL}/admin/jobs/embeddings/status`, { headers }).then(responseBody).then((status) => { setEmbeddingStatus(status); setNotice((previous) => previous || `AI matching: ${status.ready ?? 0} jobs ready, ${status.processing ?? 0} processing, ${status.failed ?? 0} failed.`); }).catch(() => {}); } }, []);
  const change = (event) => setJob({ ...job, [event.target.name]: event.target.value });
  async function save(event) { event.preventDefault(); setSaving(true); setNotice(""); try { const payload = { ...job, minExperienceYears: job.minExperienceYears === "" || job.minExperienceYears == null ? null : Number(job.minExperienceYears), maxExperienceYears: job.maxExperienceYears === "" || job.maxExperienceYears == null ? null : Number(job.maxExperienceYears) }; const response = await fetch(`${API_BASE_URL}/admin/jobs${editingId ? `/${editingId}` : ""}`, { method: editingId ? "PUT" : "POST", headers, body: JSON.stringify(payload) }); await responseBody(response); setNotice(editingId ? "Job updated." : "Job created."); setEditingId(null); setJob(blankJob); load(); } catch (e) { setNotice(e.message); } finally { setSaving(false); } }
  function edit(item) { setJob({ ...blankJob, ...item, companyWebsite: item.companyWebsite || "", companyLocation: item.companyLocation || "" }); setEditingId(item.id); setNotice(`Editing job #${item.id} | Source: ${item.source || "Manual"} | Validation: ${item.validationStatus || "unknown"}${item.sourceUrl ? ` | ${item.sourceUrl}` : ""}`); window.scrollTo({ top: 0, behavior: "smooth" }); }
  async function remove(id) { if (!window.confirm("Delete this job permanently?")) return; try { const response = await fetch(`${API_BASE_URL}/admin/jobs/${id}`, { method: "DELETE", headers }); await responseBody(response); setNotice("Job deleted."); load(); } catch (e) { setNotice(e.message); } }
  async function importJobs() { setSyncing(true); setNotice("Importing jobs and validating listings…"); try { const response = await fetch(`${API_BASE_URL}/admin/jobs/import`, { method: "POST", headers }); const body = await responseBody(response); setNotice(`${body.imported} jobs imported.`); load(); } catch (e) { setNotice(e.message); } finally { setSyncing(false); } }
  async function syncSource(source) { setSyncing(true); setNotice(`Syncing and validating ${source} jobs…`); try { const response = await fetch(`${API_BASE_URL}/admin/jobs/sync?source=${source}`, { method: "POST", headers }); const body = await responseBody(response); setSyncStatus(body); setNotice(`${source} sync complete: ${body.newJobs ?? body.imported ?? 0} new, ${body.publishedJobs ?? 0} published, ${body.needsReviewJobs ?? 0} flagged, ${body.totalJobs ?? 0} total. Valid listings publish automatically; flagged listings stay in draft for review.`); load(); } catch (e) { setNotice(e.message); } finally { setSyncing(false); } }
  async function processEmbeddings() { setEmbeddingBusy(true); setNotice("Preparing the next 20-job AI matching batch…"); try { const body = await responseBody(await fetch(`${API_BASE_URL}/admin/jobs/embeddings/rebuild?limit=20`, { method: "POST", headers })); setNotice(`${body.queued ?? 0} jobs queued for AI matching. Processing continues in the background.`); const status = await responseBody(await fetch(`${API_BASE_URL}/admin/jobs/embeddings/status`, { headers })); setEmbeddingStatus(status); window.setTimeout(() => fetch(`${API_BASE_URL}/admin/jobs/embeddings/status`, { headers }).then(responseBody).then(setEmbeddingStatus).catch(() => {}), 2500); } catch (e) { setNotice(e.message); } finally { setEmbeddingBusy(false); } }
  const field = (label, name, type = "text", placeholder = "") => <label>{label}<input name={name} type={type} value={job[name] ?? ""} onChange={change} placeholder={placeholder} required={["title", "companyName", "expiryDate"].includes(name)} /></label>;
  const changeGroupPage = (key, nextPage) => { setGroupPages((currentPages) => ({ ...currentPages, [key]: nextPage })); window.setTimeout(() => { const section = document.querySelector(`.job-list-${key}`); if (section) window.scrollTo({ top: Math.max(0, section.getBoundingClientRect().top + window.scrollY - 24), behavior: "smooth" }); }, 0); };
  if (syncing) return <section className="admin-jobs"><section className="content-card sync-progress" aria-live="polite"><RefreshCw size={22} className="spin" /><h3>Import/sync in progress…</h3><p>Fetching new listings, checking deadlines and duplicates, then publishing valid jobs automatically.</p></section></section>;
  if (loadingJobs) return <section className="admin-jobs"><section className="content-card sync-progress" aria-live="polite"><RefreshCw size={22} className="spin" /><h3>Loading jobs…</h3><p>Fetching the latest listings and preparing the admin review queue.</p></section></section>;
  const jobGroups = (() => { const groups = [
    { key: "published", title: "Published jobs", description: "Validated listings visible to students.", jobs: jobs.filter((item) => item.status === "published") },
    { key: "review", title: "Draft / needs review", description: "Incomplete or flagged listings waiting for admin review.", jobs: jobs.filter((item) => item.status === "draft") },
    { key: "closed", title: "Closed / expired", description: "Listings no longer shown in recommendations.", jobs: jobs.filter((item) => item.status === "closed") }
  ]; const pageSize = 10; groups.forEach((group) => { const allJobs = group.jobs; const totalPages = Math.max(1, Math.ceil(allJobs.length / pageSize)); const page = Math.min(groupPages[group.key] || 1, totalPages); const visibleJobs = allJobs.slice((page - 1) * pageSize, page * pageSize); const pageNumbers = [...new Set([1, 2, 3, page - 1, page, page + 1, totalPages])].filter((number) => number >= 1 && number <= totalPages).sort((a, b) => a - b); const paginationItems = pageNumbers.flatMap((number, index) => index > 0 && number - pageNumbers[index - 1] > 1 ? [`ellipsis-${number}`, number] : [number]); Object.defineProperty(group, "jobs", { value: { length: allJobs.length, map: () => [...visibleJobs.map((item) => renderJob(item)), ...(totalPages > 1 ? [<nav className="job-pagination" aria-label={`${group.title} pagination`} key={`${group.key}-pagination`}><button type="button" disabled={page === 1} onClick={() => changeGroupPage(group.key, Math.max(1, page - 1))}>Previous</button>{paginationItems.map((item) => typeof item === "number" ? <button type="button" aria-label={`Go to page ${item}`} className={item === page ? "active" : ""} key={`${group.key}-page-${item}`} onClick={() => changeGroupPage(group.key, item)}>{item}</button> : <span className="page-ellipsis" aria-hidden="true" key={`${group.key}-${item}`}>…</span>)}<button type="button" disabled={page === totalPages} onClick={() => changeGroupPage(group.key, Math.min(totalPages, page + 1))}>Next</button><small>Page {page} of {totalPages}</small></nav>] : [])] } }); }); return groups; })();
  const renderJob = (item) => { const sourceLink = item.sourceUrl || item.companyWebsite; return <article key={item.id}><div><b>{item.title}</b><small>{item.companyName} · {item.location || "No location"}</small><small className="job-source-meta">Source: {item.source || "Manual"} · Validation: {item.validationStatus || "unknown"}</small></div>{sourceLink ? <a className={`admin-job-source-link ${item.status}`} href={sourceLink} target="_blank" rel="noreferrer">View source <ExternalLink size={13} /></a> : <span className="admin-job-source-missing" title="No external or company link is available">No source link</span>}<span className={`status ${item.status}`}>{item.status}</span><span>{item.expiryDate || "—"}</span><div className="table-actions"><button type="button" onClick={() => edit(item)} title="Edit"><Pencil size={15} /></button><button type="button" onClick={() => remove(item.id)} title="Delete"><Trash2 size={15} /></button></div></article>; };
  return <section className="admin-jobs"><div className="content-intro compact"><div><p className="eyebrow"><BriefcaseBusiness size={14} /> Opportunity management</p><h2>Publish and manage jobs.</h2><p>Sync all upcoming BDJobs listings, then review flagged records before publishing.</p></div><div className="row"><Button className="quiet" type="button" onClick={importJobs}><RefreshCw size={15} /> Import from API</Button><Button className="quiet" type="button" onClick={() => syncSource("bdjobs")}><RefreshCw size={15} /> Sync BDJobs</Button></div></div>{embeddingStatus && <section className="content-card ai-processing-panel"><div><p className="eyebrow"><Sparkles size={14} /> AI matching pipeline</p><h3>{embeddingStatus.ready ?? 0} jobs ready for semantic matching</h3><p>{embeddingStatus.processing ?? 0} processing · {embeddingStatus.failed ?? 0} failed · model {embeddingStatus.model || "not configured"}</p></div><div className="row"><span className={`ai-config-status ${embeddingStatus.configured ? "ready" : "missing"}`}>{embeddingStatus.configured ? "Gemini connected" : "Gemini key missing"}</span><Button className="quiet" type="button" onClick={processEmbeddings} disabled={embeddingBusy || !embeddingStatus.configured}><RefreshCw size={15} className={embeddingBusy ? "spin" : ""} />{embeddingBusy ? "Queueing…" : "Process next 20"}</Button></div></section>}<form className="data-form job-form" onSubmit={save}><div className="form-row-title"><h3>{editingId ? "Edit job" : "Add a new job"}</h3>{editingId && <button className="text-button" type="button" onClick={() => { setEditingId(null); setJob(blankJob); setNotice(""); }}>Cancel editing</button>}</div><div className="form-grid three">{field("Job title", "title", "text", "Software Engineer Intern")}{field("Company name", "companyName", "text", "Company Ltd.")}{field("Job location", "location", "text", "Dhaka")}<label>Employment type<select name="employmentType" value={job.employmentType} onChange={change}><option value="internship">Internship</option><option value="part_time">Part time</option><option value="full_time">Full time</option><option value="contract">Contract</option></select></label><label>Work mode<select name="workMode" value={job.workMode} onChange={change}><option value="onsite">Onsite</option><option value="hybrid">Hybrid</option><option value="remote">Remote</option></select></label><label>Status<select name="status" value={job.status} onChange={change}><option value="draft">Draft</option><option value="published">Published</option><option value="closed">Closed</option></select></label>{field("Deadline", "expiryDate", "date")}{field("Min experience (years)", "minExperienceYears", "number", "0")}{field("Max experience (years)", "maxExperienceYears", "number", "5")}{field("Salary text", "salaryText", "text", "BDT 20,000/month")}{field("Company website", "companyWebsite", "url", "https://company.com")}</div><label className="full-field">Job description<textarea name="description" value={job.description} onChange={change} required rows="5" placeholder="Responsibilities, requirements, and application instructions..." /></label>{notice && <p className={/(created|updated|deleted|imported|complete|Importing|Syncing)/.test(notice) ? "form-success" : "form-error"}>{notice}</p>}<Button type="submit" disabled={saving}><Plus size={16} />{saving ? "Saving..." : editingId ? "Update job" : "Create job"}</Button></form>{jobGroups.map((group) => <section className={`content-card job-list job-list-${group.key}`} key={group.key}><div className="list-heading"><div><h3>{group.title}</h3><small>{group.description}</small></div><span>{group.jobs.length}</span></div>{group.jobs.length ? <div className="job-table">{group.jobs.map(renderJob)}</div> : <p className="muted">No {group.title.toLowerCase()} right now.</p>}</section>)}</section>;
  return <section className="admin-jobs"><div className="content-intro compact"><div><p className="eyebrow"><BriefcaseBusiness size={14} /> Opportunity management</p><h2>Publish and manage jobs.</h2><p>Import from the existing provider or sync public BDJobs listings into drafts for validation and approval.</p></div><div className="row"><Button className="quiet" type="button" onClick={importJobs}><RefreshCw size={15} /> Import from API</Button><Button className="quiet" type="button" onClick={() => syncSource("bdjobs")}><RefreshCw size={15} /> Sync BDJobs</Button></div></div><form className="data-form job-form" onSubmit={save}><div className="form-row-title"><h3>{editingId ? "Edit job" : "Add a new job"}</h3>{editingId && <button className="text-button" type="button" onClick={() => { setEditingId(null); setJob(blankJob); setNotice(""); }}>Cancel editing</button>}</div><div className="form-grid three">{field("Job title", "title", "text", "Software Engineer Intern")}{field("Company name", "companyName", "text", "Company Ltd.")}{field("Job location", "location", "text", "Dhaka")}<label>Employment type<select name="employmentType" value={job.employmentType} onChange={change}><option value="internship">Internship</option><option value="part_time">Part time</option><option value="full_time">Full time</option><option value="contract">Contract</option></select></label><label>Work mode<select name="workMode" value={job.workMode} onChange={change}><option value="onsite">Onsite</option><option value="hybrid">Hybrid</option><option value="remote">Remote</option></select></label><label>Status<select name="status" value={job.status} onChange={change}><option value="draft">Draft</option><option value="published">Published</option><option value="closed">Closed</option></select></label>{field("Deadline", "expiryDate", "date")}{field("Min experience (years)", "minExperienceYears", "number", "0")}{field("Max experience (years)", "maxExperienceYears", "number", "5")}{field("Salary text", "salaryText", "text", "BDT 20,000/month")}{field("Company website", "companyWebsite", "url", "https://company.com")}</div><label className="full-field">Job description<textarea name="description" value={job.description} onChange={change} required rows="5" placeholder="Responsibilities, requirements, and application instructions..." /></label>{notice && <p className={/(created|updated|deleted|imported|Syncing)/.test(notice) ? "form-success" : "form-error"}>{notice}</p>}<Button type="submit" disabled={saving}><Plus size={16} />{saving ? "Saving..." : editingId ? "Update job" : "Create job"}</Button></form><section className="content-card job-list"><div className="list-heading"><h3>All jobs</h3><span>{jobs.length} total</span></div>{jobs.length ? <div className="job-table">{jobs.map((item) => <article key={item.id}><div><b>{item.title}</b><small>{item.companyName} · {item.location || "No location"}</small></div><span className={`status ${item.status}`}>{item.status}</span><span>{item.expiryDate}</span><div className="table-actions"><button onClick={() => edit(item)} title="Edit"><Pencil size={15} /></button><button onClick={() => remove(item.id)} title="Delete"><Trash2 size={15} /></button></div></article>)}</div> : <p className="muted">No jobs yet. Use the form above to create the first one.</p>}</section></section>;
}

function StudentOverview({ go }) {
  const current = getSession(); const [snapshot, setSnapshot] = useState({ profile: blankProfile, applications: [], resumes: [], documents: [], jobs: [] }); const [loading, setLoading] = useState(true);
  useEffect(() => { const headers = { "X-User-Id": current?.id || "" }; if (!current?.id) { setLoading(false); return; } Promise.all([fetch(`${API_BASE_URL}/profiles/${current.id}`, { headers }).then(responseBody).catch(() => blankProfile), fetch(`${API_BASE_URL}/applications`, { headers }).then(responseBody).catch(() => []), fetch(`${API_BASE_URL}/vault/resumes`, { headers }).then(responseBody).catch(() => []), fetch(`${API_BASE_URL}/vault/documents`, { headers }).then(responseBody).catch(() => []), fetch(`${API_BASE_URL}/jobs/matches`, { headers }).then(responseBody).catch(() => [])]).then(([profile, applications, resumes, documents, jobs]) => setSnapshot({ profile: { ...blankProfile, ...profile }, applications, resumes, documents, jobs })).finally(() => setLoading(false)); }, []);
  const profileFields = [snapshot.profile.university, snapshot.profile.degree, snapshot.profile.graduationYear, snapshot.profile.experienceYears, snapshot.profile.targetRole, snapshot.profile.location, snapshot.profile.skills, snapshot.profile.hobbies, snapshot.profile.bio].filter((value) => value !== null && value !== undefined && value !== "").length; const readiness = Math.round((profileFields / 9) * 100); const documents = snapshot.resumes.length + snapshot.documents.length; const profileComplete = profileFields === 9; const cvComplete = documents > 0; const applicationsStarted = snapshot.applications.length > 0; const nextAction = !snapshot.profile.targetRole ? ["Add a target role", "Tell CareerForge what direction you want to explore.", "/student/profile", Target] : documents === 0 ? ["Create your first CV", "Save a CV version before you start applying.", "/student/vault", FileText] : ["Explore job matches", "Find published opportunities that fit your direction.", "/student/jobs", BriefcaseBusiness];
  const [nextTitle, nextCopy, nextRoute, NextIcon] = nextAction;
  return <section className="student-overview"><header className="student-overview-head"><div><h2>Welcome back, {current?.name || "Student"}.</h2><p>Here is a clear view of the work that moves your career forward.</p></div><Button className="quiet" onClick={() => go("/student/profile")}>View profile <ArrowRight size={15} /></Button></header><div className="student-dashboard-grid"><article className={`readiness-card${profileComplete ? " is-complete" : ""}`}><div><p>{profileComplete ? "CAREER READY" : "CAREER READINESS"}</p><h3>{loading ? "—" : `${readiness}%`}</h3><span>{profileComplete ? "All 9 profile details complete" : `${profileFields}/9 profile details added`}</span></div><div className="readiness-ring" style={{ "--progress": `${readiness * 3.6}deg` }}><i>{profileComplete ? <BadgeCheck size={25} /> : <Target size={24} />}</i></div><footer><span>{profileComplete ? "Profile complete — your career recommendations can now stay focused on your goals." : "Complete your profile to improve your next-step recommendations."}</span><button onClick={() => go("/student/profile")}>{profileComplete ? "View profile" : "Improve profile"} <ArrowRight size={14} /></button></footer></article><article className="workspace-summary"><div className="summary-head"><div><p>YOUR WORKSPACE</p><h3>Progress at a glance</h3></div><span>{loading ? "…" : "Live"}</span></div><div className="summary-stats"><button onClick={() => go("/student/vault")}><FileText size={18} /><b>{loading ? "—" : documents}</b><small>CVs &amp; files</small></button><button onClick={() => go("/student/jobs")}><BriefcaseBusiness size={18} /><b>{loading ? "—" : snapshot.jobs.length}</b><small>Your job matches</small></button><button onClick={() => go("/student/jobs")}><ClipboardCheck size={18} /><b>{loading ? "—" : snapshot.applications.length}</b><small>Applications</small></button></div></article><article className="next-step-card"><span><NextIcon size={20} /></span><div><p>NEXT BEST STEP</p><h3>{nextTitle}</h3><small>{nextCopy}</small></div><button onClick={() => go(nextRoute)} aria-label={nextTitle}><ArrowRight size={17} /></button></article><article className="career-path-card"><div className="summary-head"><div><p>CAREER PATH</p><h3>Your application rhythm</h3></div><button onClick={() => go("/student/jobs")}>View jobs</button></div><div className="path-track"><span className={profileComplete ? "done" : "active"}><i>1</i><b>Profile</b><small>{profileComplete ? "Complete" : "In progress"}</small></span><span className={profileComplete ? cvComplete ? "done" : "active" : "locked"}><i>2</i><b>CV</b><small>{profileComplete ? cvComplete ? "Complete" : "In progress" : "Complete profile first"}</small></span><span className={profileComplete && cvComplete ? applicationsStarted ? "done" : "active" : "locked"}><i>3</i><b>Apply</b><small>{profileComplete && cvComplete ? applicationsStarted ? "Complete" : "In progress" : "Complete CV first"}</small></span></div></article></div></section>;
}

function StudentEvents({ go }) {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState("");

  useEffect(() => {
    let active = true;
    fetch(`${API_BASE_URL}/events`)
      .then(responseBody)
      .then((items) => { if (active) setEvents(Array.isArray(items) ? items : []); })
      .catch((error) => { if (active) setNotice(error.message || "Events could not be loaded right now."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);

  const eventDate = (value) => {
    if (!value) return "Date to be announced";
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? "Date to be announced" : date.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
  };

  return <section className="student-events-page">
    <header className="events-hero">
      <div><p className="eyebrow"><CalendarDays size={14} /> CAREER CALENDAR</p><h2>Make room for the moments that move you forward.</h2><p>CareerForge gathers workshops, employer sessions, and campus opportunities in one calm calendar.</p></div>
      <div className="events-hero-date"><CalendarDays size={23} /><span><b>{loading ? "Loading events" : `${events.length} published event${events.length === 1 ? "" : "s"}`}</b><small>Stay ready for what is next</small></span></div>
    </header>
    {notice && <p className="form-error">{notice}</p>}
    {loading ? <section className="events-empty-state content-card"><span className="events-empty-icon"><RefreshCw size={28} /></span><div><p className="eyebrow">YOUR UPCOMING EVENTS</p><h3>Loading published events…</h3><p>Checking the CareerForge calendar for the latest workshops and opportunities.</p></div></section>
      : events.length ? <section className="student-event-list content-card"><div className="student-event-list-head"><div><p className="eyebrow">YOUR UPCOMING EVENTS</p><h3>Plan your next opportunity.</h3><p>These events were published by the CareerForge team.</p></div><span>{events.length} upcoming</span></div><div className="student-event-grid">{events.map((event) => <article className="student-event-card" key={event.id}><div className="student-event-card-top"><span><CalendarDays size={18} /></span><small>{event.category || "Career event"}</small></div><h3>{event.title}</h3>{event.description && <p>{event.description}</p>}<div className="student-event-meta"><span><CalendarDays size={14} /> {eventDate(event.startsAt)}</span>{event.location && <span><MapPin size={14} /> {event.location}</span>}{event.capacity && <span><Users size={14} /> {event.capacity} places</span>}</div>{event.eventUrl && <a href={event.eventUrl} target="_blank" rel="noreferrer">Open event details <ArrowRight size={14} /></a>}</article>)}</div></section>
      : <section className="events-empty-state content-card"><span className="events-empty-icon"><CalendarDays size={28} /></span><div><p className="eyebrow">YOUR UPCOMING EVENTS</p><h3>No events have been published yet.</h3><p>When a CareerForge administrator publishes a workshop, employer session, or deadline reminder, you will see it here.</p></div><Button className="quiet" onClick={() => go("/student/resources")}>Explore resources <ArrowRight size={15} /></Button></section>}
    <section className="event-ready-grid">
      <article><span><CircleUserRound size={19} /></span><div><b>Keep your profile current</b><p>Make it easy to join events and share your professional direction.</p><button onClick={() => go("/student/profile")}>Update profile <ArrowRight size={14} /></button></div></article>
      <article><span><FileText size={19} /></span><div><b>Bring your best CV</b><p>Save a current CV so you are ready when an employer opportunity arrives.</p><button onClick={() => go("/student/vault")}>Open Career Vault <ArrowRight size={14} /></button></div></article>
      <article><span><BookOpen size={19} /></span><div><b>Build a useful skill</b><p>Use the library while you wait for the next workshop or campus session.</p><button onClick={() => go("/student/resources")}>Browse resources <ArrowRight size={14} /></button></div></article>
    </section>
  </section>;
}

function AdminSettings({ go }) {
  const areas = [[Users, "Student experience", "Review student accounts and make sure their careers can progress without friction.", "/admin/students", "Open students"], [BriefcaseBusiness, "Opportunity flow", "Publish roles, review drafts, and keep application activity clear for every student.", "/admin/jobs", "Manage jobs"], [BookOpen, "Learning library", "Keep assessment, resource, and event content useful, current, and easy to discover.", "/admin/resources", "Manage learning"], [MessageCircle, "Community health", "Moderate activity and share official announcements from the community workspace.", "/admin/community", "Open community"]];
  return <section className="admin-settings-page">
    <header className="admin-settings-hero"><div><p className="eyebrow"><Settings size={14} /> PLATFORM GUIDE</p><h2>Run a consistent CareerForge experience.</h2><p>Operational controls live with the feature they affect, so every decision stays close to its workflow.</p></div><span><ShieldCheck size={27} /><b>Workflow-first</b><small>No hidden settings</small></span></header>
    <section className="settings-principles"><article><b>01</b><div><h3>Student-first controls</h3><p>Account and profile operations stay in Students, where their impact is easiest to review.</p></div></article><article><b>02</b><div><h3>Content stays contextual</h3><p>Jobs, assessments, resources, and events are managed from their own dedicated workspaces.</p></div></article><article><b>03</b><div><h3>Community stays accountable</h3><p>Moderation, reports, and official announcements remain together in one review queue.</p></div></article></section>
    <section className="settings-area-grid">{areas.map(([Icon, title, copy, route, action]) => <article key={title}><span><Icon size={21} /></span><h3>{title}</h3><p>{copy}</p><button onClick={() => go(route)}>{action} <ArrowRight size={15} /></button></article>)}</section>
  </section>;
}

function CommunityFeed() {
  const current = getSession(); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" }; const [posts, setPosts] = useState([]); const [draft, setDraft] = useState(""); const [comments, setComments] = useState({}); const [notice, setNotice] = useState("");
  const load = () => fetch(`${API_BASE_URL}/community/posts`, { headers }).then(responseBody).then(setPosts).catch((error) => setNotice(error.message));
  useEffect(() => { load(); }, []);
  const publish = async (event) => { event.preventDefault(); if (!draft.trim()) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts`, { method: "POST", headers, body: JSON.stringify({ content: draft }) })); setDraft(""); load(); } catch (error) { setNotice(error.message); } };
  const like = async (postId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/likes`, { method: "POST", headers })); load(); } catch (error) { setNotice(error.message); } };
  const comment = async (event, postId) => { event.preventDefault(); const content = comments[postId]?.trim(); if (!content) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/comments`, { method: "POST", headers, body: JSON.stringify({ content }) })); setComments((old) => ({ ...old, [postId]: "" })); load(); } catch (error) { setNotice(error.message); } };
  return <section className="community-feed content-card"><div className="list-heading"><h3>Community feed</h3><span>{posts.length} posts</span></div><form className="post-composer" onSubmit={publish}><textarea value={draft} onChange={(event) => setDraft(event.target.value)} maxLength="5000" placeholder="Share a career question, resource, or achievement..." /><Button disabled={!draft.trim()} type="submit"><Plus size={15} /> Publish</Button></form>{notice && <p className="form-error">{notice}</p>}<div className="feed-list">{posts.map((post) => <article className="feed-post" key={post.id}><header><span>{post.authorName?.slice(0, 1)?.toUpperCase()}</span><div><b>{post.authorName}</b><small>Student community</small></div></header><p>{post.content}</p><footer><button className={post.likedByMe ? "liked" : ""} onClick={() => like(post.id)}>♥ {post.likeCount}</button><span>{post.commentCount} comment{post.commentCount === 1 ? "" : "s"}</span></footer><div className="post-comments">{post.comments.map((item) => <p key={item.id}><b>{item.authorName}</b>{item.content}</p>)}<form onSubmit={(event) => comment(event, post.id)}><input value={comments[post.id] || ""} onChange={(event) => setComments((old) => ({ ...old, [post.id]: event.target.value }))} placeholder="Write a comment..." maxLength="2000" /><button disabled={!comments[post.id]?.trim()} type="submit">Comment</button></form></div></article>)}{!posts.length && <p className="muted">Be the first student to share an idea with the community.</p>}</div></section>;
}

function CommunityEnhanced() {
  const current = getSession(); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const [posts, setPosts] = useState([]); const [draft, setDraft] = useState(""); const [mediaUrl, setMediaUrl] = useState(""); const [topicTags, setTopicTags] = useState(""); const [comments, setComments] = useState({}); const [openComments, setOpenComments] = useState({}); const [notice, setNotice] = useState("");
  const load = () => fetch(`${API_BASE_URL}/community/posts`, { headers }).then(responseBody).then((items) => setPosts([...items].sort((first, second) => String(second.createdAt || "").localeCompare(String(first.createdAt || ""))))).catch((error) => setNotice(error.message));
  useEffect(() => { load(); }, []);
  const publish = async (event) => { event.preventDefault(); if (!draft.trim()) return; try { const post = await responseBody(await fetch(`${API_BASE_URL}/community/posts`, { method: "POST", headers, body: JSON.stringify({ content: draft, mediaUrl, topicTags }) })); setDraft(""); setMediaUrl(""); setTopicTags(""); window.dispatchEvent(new Event("community-allowance-updated")); setNotice(post.status === "pending_review" ? "Your post is pending moderator review because it matched safety rules." : "Your post is now visible in the community."); load(); } catch (error) { setNotice(error.message); } };
  const like = async (postId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/likes`, { method: "POST", headers })); load(); } catch (error) { setNotice(error.message); } };
  const comment = async (event, postId) => { event.preventDefault(); const content = comments[postId]?.trim(); if (!content) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/comments`, { method: "POST", headers, body: JSON.stringify({ content }) })); setComments((old) => ({ ...old, [postId]: "" })); setOpenComments((old) => ({ ...old, [postId]: true })); window.dispatchEvent(new Event("community-allowance-updated")); load(); } catch (error) { setNotice(error.message); } };
  const share = async (post) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${post.id}/shares`, { method: "POST", headers })); await navigator.clipboard?.writeText(`${window.location.origin}${window.location.pathname}#/student/community?post=${post.id}`); setNotice("Post link copied. Your share is counted only once."); load(); } catch (error) { setNotice(error.message); } };
  const report = async (post) => { const reason = window.prompt("Report reason: spam, fraud, harassment, misinformation, or other", "spam")?.trim().toLowerCase(); if (!reason) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${post.id}/reports?reason=${encodeURIComponent(reason)}`, { method: "POST", headers })); setNotice("Report submitted for moderator review."); } catch (error) { setNotice(error.message); } };
  const deletePost = async (post) => { if (!window.confirm("Remove your post from the community?")) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${post.id}`, { method: "DELETE", headers })); setNotice("Your post was removed."); load(); } catch (error) { setNotice(error.message); } };
  return <section className="community-feed content-card"><div className="list-heading"><div><h3>Community feed</h3><small>Share career ideas. Posts are checked for spam and fraud before other students can interact with them.</small></div><span>{posts.length} posts</span></div><form className="post-composer" onSubmit={publish}><textarea value={draft} onChange={(event) => setDraft(event.target.value)} maxLength="5000" placeholder="Share a career question, resource, or achievement..." /><div className="community-post-options"><input value={mediaUrl} onChange={(event) => setMediaUrl(event.target.value)} maxLength="500" placeholder="Optional link" /><input value={topicTags} onChange={(event) => setTopicTags(event.target.value)} maxLength="500" placeholder="Topics, e.g. Java, internships" /></div><Button disabled={!draft.trim()} type="submit"><Plus size={15} /> Publish</Button></form>{notice && <p className={notice.includes("pending") || notice.includes("visible") || notice.includes("submitted") || notice.includes("removed") || notice.includes("copied") ? "form-success" : "form-error"}>{notice}</p>}<div className="feed-list community-post-stream">{posts.map((post) => <article className={`feed-post ${post.status !== "visible" ? "pending-post" : ""}`} key={post.id}><header><span>{post.authorName?.slice(0, 1)?.toUpperCase()}</span><div><b>{post.authorName}</b><small>{post.status === "visible" ? "Student community" : post.status === "pending_review" ? "Pending moderator review" : "Removed"}</small></div><div className="post-header-actions">{post.status === "visible" && post.authorName !== current?.name && <button className="post-report" onClick={() => report(post)}>Report</button>}{post.authorName === current?.name && <button className="text-button" onClick={() => deletePost(post)}>Delete</button>}</div></header><p>{post.content}</p>{post.mediaUrl && <a className="post-link" href={post.mediaUrl} target="_blank" rel="noreferrer">Open shared link</a>}{post.topicTags && <div className="post-tags">{post.topicTags.split(",").map((tag) => tag.trim()).filter(Boolean).map((tag) => <span key={tag}>#{tag}</span>)}</div>}{post.status === "visible" ? <><footer><button className={post.likedByMe ? "liked" : ""} onClick={() => like(post.id)}>♥ {post.likeCount}</button><button className={openComments[post.id] ? "active" : ""} onClick={() => setOpenComments((old) => ({ ...old, [post.id]: !old[post.id] }))} aria-expanded={Boolean(openComments[post.id])}>{openComments[post.id] ? "Hide comments" : `${post.commentCount} comment${post.commentCount === 1 ? "" : "s"}`}</button><button className="post-share" onClick={() => share(post)}>Share {post.shareCount}</button></footer>{openComments[post.id] && <div className="post-comments"><div className="post-comment-list">{post.comments.length ? post.comments.map((item) => <p key={item.id}><b>{item.authorName}</b>{item.content}</p>) : <p className="comment-empty">Be the first to comment.</p>}</div><form onSubmit={(event) => comment(event, post.id)}><input value={comments[post.id] || ""} onChange={(event) => setComments((old) => ({ ...old, [post.id]: event.target.value }))} placeholder="Write a comment..." maxLength="2000" /><button disabled={!comments[post.id]?.trim()} type="submit">Comment</button></form></div>}</> : <p className="pending-note">Only you and community moderators can see this post until it is reviewed.</p>}</article>)}{!posts.length && <p className="muted">Be the first student to share an idea with the community.</p>}</div></section>;
}

function CommunityAllowanceCard() {
  const current = getSession(); const [allowance, setAllowance] = useState(null); const [now, setNow] = useState(Date.now());
  const load = () => fetch(`${API_BASE_URL}/community/posts/allowance`, { headers: { "X-User-Id": current?.id || "" } }).then(responseBody).then(setAllowance).catch(() => setAllowance(null));
  useEffect(() => { load(); const refresh = () => load(); window.addEventListener("community-allowance-updated", refresh); const timer = window.setInterval(() => setNow(Date.now()), 1000); return () => { window.removeEventListener("community-allowance-updated", refresh); window.clearInterval(timer); }; }, []);
  const seconds = allowance?.refreshAt ? Math.max(0, Math.ceil((new Date(allowance.refreshAt).getTime() - now) / 1000)) : 0; const countdown = `${String(Math.floor(seconds / 3600)).padStart(2, "0")}:${String(Math.floor(seconds % 3600 / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
  return <section className="community-allowance"><div className="allowance-icon">⚡</div><div><p>COMMUNITY POINTS</p><h3>{allowance ? `${allowance.points} / 10 available` : "Loading points…"}</h3><small>Posts and comments cost 1 point. Likes, shares, and reports are free.</small></div><div className="allowance-refresh"><small>FULL REFRESH IN</small><strong>{countdown}</strong></div></section>;
}

function Community() { return <><CommunityAllowanceCard /><CommunityEnhanced /></>; }

function CommunityChat() {
  const current = getSession(); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const [students, setStudents] = useState([]); const [connections, setConnections] = useState([]); const [posts, setPosts] = useState([]); const [selected, setSelected] = useState(null); const [messages, setMessages] = useState([]); const [search, setSearch] = useState(""); const [draft, setDraft] = useState(""); const [postDraft, setPostDraft] = useState(""); const [commentDrafts, setCommentDrafts] = useState({}); const [notice, setNotice] = useState(""); const [live, setLive] = useState(false);
  const load = async (term = search) => { if (!current?.id) return; try { const [people, links, feed] = await Promise.all([fetch(`${API_BASE_URL}/community/students?query=${encodeURIComponent(term)}`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/community/connections`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/community/posts`, { headers }).then(responseBody)]); setStudents(people); setConnections(links); setPosts(feed); } catch (error) { setNotice(error.message); } };
  useEffect(() => { load(""); }, []);
  useEffect(() => { if (!selected?.id) { setMessages([]); return; } fetch(`${API_BASE_URL}/community/connections/${selected.id}/messages`, { headers }).then(responseBody).then(setMessages).catch((error) => setNotice(error.message)); }, [selected?.id]);
  useEffect(() => {
    if (!current?.id) return undefined;
    const base = API_BASE_URL.startsWith("http") ? API_BASE_URL.replace(/^http/, "ws") : `${window.location.protocol === "https:" ? "wss" : "ws"}://${window.location.host}${API_BASE_URL}`;
    const socket = new WebSocket(`${base}/ws/chat?userId=${encodeURIComponent(current.id)}`);
    socket.onopen = () => setLive(true); socket.onclose = () => setLive(false);
    socket.onmessage = (event) => { try { const packet = JSON.parse(event.data); if (packet.type === "message") { const incoming = packet.message; setMessages((old) => old.some((item) => item.id === incoming.id) ? old : [...old, incoming]); load(); } if (packet.type === "error") setNotice(packet.message); } catch { } };
    window.communitySocket = socket;
    return () => { socket.close(); if (window.communitySocket === socket) window.communitySocket = null; };
  }, [current?.id]);
  const request = async (studentId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/connections`, { method: "POST", headers, body: JSON.stringify({ studentId }) })); setNotice("Connection request sent."); load(); } catch (error) { setNotice(error.message); } };
  const createPost = async (event) => { event.preventDefault(); if (!postDraft.trim()) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts`, { method: "POST", headers, body: JSON.stringify({ content: postDraft }) })); setPostDraft(""); setNotice("Your community post is published."); load(); } catch (error) { setNotice(error.message); } };
  const likePost = async (postId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/likes`, { method: "POST", headers })); load(); } catch (error) { setNotice(error.message); } };
  const addComment = async (event, postId) => { event.preventDefault(); const content = commentDrafts[postId]?.trim(); if (!content) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/posts/${postId}/comments`, { method: "POST", headers, body: JSON.stringify({ content }) })); setCommentDrafts((old) => ({ ...old, [postId]: "" })); load(); } catch (error) { setNotice(error.message); } };
  const accept = async (connectionId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/connections/${connectionId}/accept`, { method: "PUT", headers })); setNotice("Connection accepted. You can now chat live."); load(); } catch (error) { setNotice(error.message); } };
  const remove = async (connectionId) => { if (!window.confirm("Remove this connection and its messages?")) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/connections/${connectionId}`, { method: "DELETE", headers })); if (selected?.id === connectionId) setSelected(null); setNotice("Connection removed."); load(); } catch (error) { setNotice(error.message); } };
  const send = async (event) => { event.preventDefault(); const content = draft.trim(); if (!content || !selected) return; const socket = window.communitySocket; if (socket?.readyState === WebSocket.OPEN) { socket.send(JSON.stringify({ connectionId: selected.id, content })); setDraft(""); return; } try { const message = await responseBody(await fetch(`${API_BASE_URL}/community/connections/${selected.id}/messages`, { method: "POST", headers, body: JSON.stringify({ content }) })); setMessages((old) => [...old, message]); setDraft(""); } catch (error) { setNotice(error.message); } };
  const accepted = connections.filter((connection) => connection.status === "accepted"); const pending = connections.filter((connection) => connection.status === "pending");
  return <section className="community-page"><div className="content-intro compact"><div><p className="eyebrow"><MessageCircle size={14} /> STUDENT COMMUNITY</p><h2>Connect, then chat in real time.</h2><p>Discover classmates, accept connections, and exchange career ideas through a live client-server socket channel.</p></div><span className={`chat-live ${live ? "online" : ""}`}>{live ? "Live chat online" : "Connecting..."}</span></div>{notice && <p className="form-success">{notice}</p>}<div className="community-layout"><section className="content-card community-directory"><div className="list-heading"><h3>Discover students</h3><span>{students.length} shown</span></div><div className="community-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => event.key === "Enter" && load()} placeholder="Search student name" /><button onClick={() => load()} aria-label="Search"><ArrowRight size={15} /></button></div><div className="person-list">{students.map((student) => <article key={student.id}><span>{student.name?.slice(0, 1)?.toUpperCase()}</span><div><b>{student.name}</b><small>{student.email}</small></div>{student.connectionStatus === "accepted" ? <button className="text-button" onClick={() => setSelected(connections.find((item) => item.id === student.connectionId) || null)}>Chat</button> : student.connectionStatus === "pending" && !student.outgoing ? <button className="text-button" onClick={() => accept(student.connectionId)}>Accept</button> : student.connectionStatus === "pending" ? <small>Requested</small> : <button className="text-button" onClick={() => request(student.id)}>Connect</button>}</article>)}{!students.length && <p className="muted">No students found. Try a different name.</p>}</div></section><section className="content-card community-connections"><div className="list-heading"><h3>Your connections</h3><span>{accepted.length} active</span></div><div className="connection-list">{pending.map((connection) => <article key={connection.id}><div><b>{connection.studentName}</b><small>{connection.outgoing ? "Request sent" : "Wants to connect"}</small></div><div>{!connection.outgoing && <button className="text-button" onClick={() => accept(connection.id)}>Accept</button>}<button className="icon-action danger" onClick={() => remove(connection.id)} title="Remove connection"><Trash2 size={14} /></button></div></article>)}{accepted.map((connection) => <article key={connection.id} className={selected?.id === connection.id ? "selected" : ""}><button className="connection-select" onClick={() => setSelected(connection)}><span>{connection.studentName?.slice(0, 1)?.toUpperCase()}</span><div><b>{connection.studentName}</b><small>{connection.unreadCount ? `${connection.unreadCount} unread message${connection.unreadCount > 1 ? "s" : ""}` : "Connected"}</small></div></button><button className="icon-action danger" onClick={() => remove(connection.id)} title="Remove connection"><Trash2 size={14} /></button></article>)}{!connections.length && <p className="muted">Connect with a student to start a private conversation.</p>}</div></section><section className="content-card community-chat"><header><div><p className="eyebrow">PRIVATE CHAT</p><h3>{selected ? selected.studentName : "Choose a connection"}</h3></div>{selected && <span className="chat-live online">Socket chat</span>}</header><div className="message-list">{selected ? messages.map((message) => <article key={message.id} className={message.senderId === current?.id ? "mine" : "theirs"}><small>{message.senderId === current?.id ? "You" : message.senderName}</small><p>{message.content}</p></article>) : <p className="muted">Accepted connections can message each other instantly. This chat is stored in MySQL and delivered through WebSocket.</p>}{selected && !messages.length && <p className="muted">Start the conversation with {selected.studentName}.</p>}</div><form onSubmit={send}><input value={draft} disabled={!selected} onChange={(event) => setDraft(event.target.value)} placeholder={selected ? "Write a message..." : "Select a connection first"} maxLength="2000" /><Button disabled={!selected || !draft.trim()} type="submit">Send <ArrowRight size={15} /></Button></form></section></div></section>;
}

function Connect({ go }) {
  const current = getSession(); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const [students, setStudents] = useState([]); const [connections, setConnections] = useState([]); const [search, setSearch] = useState(""); const [notice, setNotice] = useState("");
  const load = async (term = search) => { try { const [people, links] = await Promise.all([fetch(`${API_BASE_URL}/community/students?query=${encodeURIComponent(term)}`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/community/connections`, { headers }).then(responseBody)]); setStudents(people); setConnections(links); } catch (error) { setNotice(error.message); } };
  useEffect(() => { load(""); }, []);
  const request = async (studentId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/connections`, { method: "POST", headers, body: JSON.stringify({ studentId }) })); setNotice("Connection request sent."); load(); } catch (error) { setNotice(error.message); } };
  const accept = async (connectionId) => { try { await responseBody(await fetch(`${API_BASE_URL}/community/connections/${connectionId}/accept`, { method: "PUT", headers })); setNotice("Connection accepted. Their basic profile and chat are now available."); load(); } catch (error) { setNotice(error.message); } };
  const remove = async (connectionId) => { if (!window.confirm("Remove this connection and its messages?")) return; try { await responseBody(await fetch(`${API_BASE_URL}/community/connections/${connectionId}`, { method: "DELETE", headers })); setNotice("Connection removed."); load(); } catch (error) { setNotice(error.message); } };
  const pending = connections.filter((connection) => connection.status === "pending"); const accepted = connections.filter((connection) => connection.status === "accepted");
  return <section className="connect-page"><div className="content-intro compact"><div><p className="eyebrow"><Users size={14} /> STUDENT CONNECTIONS</p><h2>Discover classmates and build your network.</h2><p>Send a request first. After it is accepted, both students can view a basic profile and begin a private real-time chat.</p></div><span className="admin-total">{accepted.length} connected</span></div>{notice && <p className="form-success">{notice}</p>}<div className="connect-layout"><section className="content-card community-directory"><div className="list-heading"><h3>Discover students</h3><span>{students.length} shown</span></div><div className="community-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => event.key === "Enter" && load()} placeholder="Search ID, name, university, or role" /><button onClick={() => load()} aria-label="Search"><ArrowRight size={15} /></button></div><div className="person-list">{students.map((student) => <article key={student.id}><span>{student.name?.slice(0, 1)?.toUpperCase()}</span><div><b>{student.name}</b><small>{student.connectionStatus === "accepted" ? "Connected student" : "CareerForge student"}</small></div>{student.connectionStatus === "accepted" ? <button className="text-button" onClick={() => go("/student/chat")}>Message</button> : student.connectionStatus === "pending" && !student.outgoing ? <button className="text-button" onClick={() => accept(student.connectionId)}>Accept</button> : student.connectionStatus === "pending" ? <button className="text-button" onClick={() => remove(student.connectionId)}>Cancel</button> : <button className="text-button" onClick={() => request(student.id)}>Add</button>}</article>)}{!students.length && <p className="muted">No students found. Try a different search.</p>}</div></section><section className="content-card connection-manager"><div className="list-heading"><h3>Your requests and connections</h3><span>{connections.length} total</span></div><div className="connection-list">{pending.map((connection) => <article key={connection.id}><div><b>{connection.studentName}</b><small>{connection.outgoing ? "Request sent" : "Wants to connect"}</small></div><div>{!connection.outgoing && <button className="text-button" onClick={() => accept(connection.id)}>Accept</button>}<button className="text-button" onClick={() => remove(connection.id)}>{connection.outgoing ? "Cancel" : "Decline"}</button></div></article>)}{accepted.map((connection) => <article key={connection.id}><div><b>{connection.studentName}</b><small>{connection.unreadCount ? `${connection.unreadCount} unread message${connection.unreadCount > 1 ? "s" : ""}` : "Profile and chat unlocked"}</small></div><div><button className="text-button" onClick={() => go("/student/chat")}>Message</button><button className="icon-action danger" onClick={() => remove(connection.id)} title="Remove connection"><Trash2 size={14} /></button></div></article>)}{!connections.length && <p className="muted">No requests yet. Find a classmate and send the first connection request.</p>}</div></section></div></section>;
}

function StudentChat() {
  const current = getSession(); const headers = { "Content-Type": "application/json", "X-User-Id": current?.id || "" };
  const [connections, setConnections] = useState([]); const [selected, setSelected] = useState(null); const [messages, setMessages] = useState([]); const [profile, setProfile] = useState(null); const [draft, setDraft] = useState(""); const [notice, setNotice] = useState(""); const [live, setLive] = useState(false); const [photoFailed, setPhotoFailed] = useState(false); const [connectionPhotoErrors, setConnectionPhotoErrors] = useState({}); const messageListRef = useRef(null);
  const loadConnections = () => fetch(`${API_BASE_URL}/community/connections`, { headers }).then(responseBody).then((items) => { const accepted = items.filter((item) => item.status === "accepted"); setConnections(accepted); setSelected((old) => old ? accepted.find((item) => item.id === old.id) || null : accepted[0] || null); }).catch((error) => setNotice(error.message));
  useEffect(() => { loadConnections(); }, []);
  useEffect(() => { if (!selected?.id) { setMessages([]); setProfile(null); return; } Promise.all([fetch(`${API_BASE_URL}/community/connections/${selected.id}/messages`, { headers }).then(responseBody), fetch(`${API_BASE_URL}/community/connections/${selected.id}/profile`, { headers }).then(responseBody)]).then(([conversation, connectedProfile]) => { setMessages(conversation); setProfile(connectedProfile); }).catch((error) => setNotice(error.message)); }, [selected?.id]);
  useEffect(() => { setPhotoFailed(false); }, [profile?.profilePhotoUrl]);
  useEffect(() => { const list = messageListRef.current; if (list) list.scrollTo({ top: list.scrollHeight, behavior: "smooth" }); }, [selected?.id, messages.length]);
  useEffect(() => { if (!current?.id) return undefined; const base = API_BASE_URL.startsWith("http") ? API_BASE_URL.replace(/^http/, "ws") : `${window.location.protocol === "https:" ? "wss" : "ws"}://${window.location.host}${API_BASE_URL}`; const socket = new WebSocket(`${base}/ws/chat?userId=${encodeURIComponent(current.id)}`); socket.onopen = () => setLive(true); socket.onclose = () => setLive(false); socket.onmessage = (event) => { try { const packet = JSON.parse(event.data); if (packet.type === "message") { const incoming = packet.message; setMessages((old) => old.some((item) => item.id === incoming.id) ? old : [...old, incoming]); loadConnections(); } if (packet.type === "presence") { const updatePresence = (connection) => Number(connection.studentId) === Number(packet.userId) ? { ...connection, online: Boolean(packet.online), lastActiveAt: packet.lastActiveAt || null } : connection; setConnections((old) => old.map(updatePresence)); setSelected((old) => old ? updatePresence(old) : old); } if (packet.type === "error") setNotice(packet.message); } catch { } }; window.communitySocket = socket; return () => { socket.close(); if (window.communitySocket === socket) window.communitySocket = null; }; }, [current?.id]);
  const send = async (event) => { event.preventDefault(); const content = draft.trim(); if (!content || !selected) return; const socket = window.communitySocket; if (socket?.readyState === WebSocket.OPEN) { socket.send(JSON.stringify({ connectionId: selected.id, content })); setDraft(""); return; } try { const message = await responseBody(await fetch(`${API_BASE_URL}/community/connections/${selected.id}/messages`, { method: "POST", headers, body: JSON.stringify({ content }) })); setMessages((old) => [...old, message]); setDraft(""); } catch (error) { setNotice(error.message); } };
  const skills = profile?.skills ? profile.skills.split(",").map((skill) => skill.trim()).filter(Boolean).slice(0, 8) : [];
  const photoUrl = typeof profile?.profilePhotoUrl === "string" && profile.profilePhotoUrl.trim() ? (profile.profilePhotoUrl.startsWith("/") ? `${API_BASE_URL}${profile.profilePhotoUrl}` : profile.profilePhotoUrl) : "";
  return <section className="student-chat-page"><div className="content-intro compact"><div><p className="eyebrow"><MessageCircle size={14} /> PRIVATE REAL-TIME CHAT</p><h2>Chat with accepted connections.</h2><p>Messages are stored securely in your project database and delivered through the live client-server socket channel.</p></div><span className={`chat-live ${live ? "online" : "offline"}`}>{live ? "Live chat online" : "Connecting..."}</span></div>{notice && <p className="form-success">{notice}</p>}<div className="chat-page-layout"><section className="content-card chat-contacts"><div className="list-heading"><h3>Connections</h3><span>{connections.length} active</span></div><div className="connection-list">{connections.map((connection) => { const contactPhoto = typeof connection.profilePhotoUrl === "string" && connection.profilePhotoUrl.trim() ? (connection.profilePhotoUrl.startsWith("/") ? `${API_BASE_URL}${connection.profilePhotoUrl}` : connection.profilePhotoUrl) : ""; return <article className={selected?.id === connection.id ? "selected" : ""} key={connection.id}><button className="connection-select" onClick={() => setSelected(connection)}><span className="connection-avatar">{contactPhoto && !connectionPhotoErrors[connection.id] ? <img src={contactPhoto} onError={() => setConnectionPhotoErrors((old) => ({ ...old, [connection.id]: true }))} alt="" /> : connection.studentName?.slice(0, 1)?.toUpperCase()}</span><div><b>{connection.studentName}</b><small className="connection-presence"><i className={`presence-dot ${connection.online ? "online" : "offline"}`} />{connection.unreadCount ? `${connection.unreadCount} unread · ` : ""}{connectionActivity(connection)}</small></div></button></article>; })}{!connections.length && <p className="muted">Accept a request in Connect before starting a chat.</p>}</div></section><section className="content-card community-chat"><header><div><p className="eyebrow">CONVERSATION</p><h3>{selected ? selected.studentName : "Choose a connection"}</h3>{selected && <p className="conversation-presence"><i className={`presence-dot ${selected.online ? "online" : "offline"}`} />{connectionActivity(selected)}</p>}</div>{selected && <span className={`chat-live ${selected.online ? "online" : "offline"}`}>Socket chat</span>}</header><div className="message-list" ref={messageListRef}>{selected ? messages.map((message) => <article key={message.id} className={message.senderId === current?.id ? "mine" : "theirs"}><small>{message.senderId === current?.id ? "You" : message.senderName}</small><p>{message.content}</p></article>) : <p className="muted">Choose a connected student to open a conversation.</p>}{selected && !messages.length && <p className="muted">Start the conversation with {selected.studentName}.</p>}</div><form onSubmit={send}><input value={draft} disabled={!selected} onChange={(event) => setDraft(event.target.value)} placeholder={selected ? "Write a message..." : "Select a connection first"} maxLength="2000" /><Button disabled={!selected || !draft.trim()} type="submit">Send <ArrowRight size={15} /></Button></form></section><aside className="content-card connected-profile"><div className="profile-avatar">{photoUrl && !photoFailed ? <img src={photoUrl} onError={() => setPhotoFailed(true)} alt={`${profile?.name || selected?.studentName || "Connected student"}'s profile`} /> : <span>{(profile?.name || selected?.studentName || "?").slice(0, 1).toUpperCase()}</span>}</div><h3>{profile?.name || selected?.studentName || "Connected student"}</h3><p>{profile?.targetRole || "Career direction not added"}</p><dl><div><dt>University</dt><dd>{profile?.university || "Not shared"}</dd></div><div><dt>Location</dt><dd>{profile?.location || "Not shared"}</dd></div><div><dt>Degree</dt><dd>{profile?.degree || "Not shared"}</dd></div></dl>{skills.length > 0 && <><small className="profile-label">SKILLS</small><div className="profile-skills">{skills.map((skill) => <span key={skill}>{skill}</span>)}</div></>}{profile?.bio && <p className="profile-bio">{profile.bio}</p>}<small className="muted">Visible because your connection has been accepted.</small></aside></div></section>;
}

function Workspace({ role, section, go }) {
  const admin = role === "admin"; const [sessionVersion, refreshSession] = useState(0); const current = getSession(); const items = admin ? adminItems : studentItems; const label = items.find(([id]) => id === section)?.[1] || "Overview"; const [query, setQuery] = useState(""); const [accountMenuState, setAccountMenuState] = useState("closed"); const accountOpen = accountMenuState === "open"; const accountVisible = accountMenuState !== "closed"; const [workspacePhotoUrl, setWorkspacePhotoUrl] = useState(""); const matches = query.trim() ? items.filter(([id, name]) => `${id} ${name}`.toLowerCase().includes(query.trim().toLowerCase())) : [];
  useEffect(() => { const update = () => refreshSession((version) => version + 1); window.addEventListener("careerforge-session-updated", update); return () => window.removeEventListener("careerforge-session-updated", update); }, []);
  useEffect(() => { if (!current?.id) { setWorkspacePhotoUrl(""); return undefined; } const profileEndpoint = admin ? `${API_BASE_URL}/account/profile` : `${API_BASE_URL}/profiles/${current.id}`; let active = true; fetch(profileEndpoint, { headers: { "X-User-Id": current.id } }).then(responseBody).then((body) => { if (!active) return; const value = body.profilePhotoUrl; setWorkspacePhotoUrl(value?.startsWith("/") ? `${API_BASE_URL}${value}` : value || ""); }).catch(() => { if (active) setWorkspacePhotoUrl(""); }); return () => { active = false; }; }, [admin, current?.id, sessionVersion]);
  useEffect(() => { const avatar = document.querySelector(".account-control .avatar"); if (!avatar) return; avatar.classList.toggle("has-photo", Boolean(workspacePhotoUrl)); if (workspacePhotoUrl) { avatar.textContent = ""; const image = document.createElement("img"); image.src = workspacePhotoUrl; image.alt = "Profile"; avatar.appendChild(image); } else if (!avatar.textContent.trim()) avatar.textContent = current?.name?.slice(0, 1)?.toUpperCase() || (admin ? "A" : "S"); }, [workspacePhotoUrl, accountOpen, query, current?.name, admin]);
  useEffect(() => { if (!accountOpen) return undefined; const closeMenu = (event) => { if (!event.target.closest(".account-control")) closeAccountMenu(); }; const closeOnEscape = (event) => { if (event.key === "Escape") closeAccountMenu(); }; document.addEventListener("pointerdown", closeMenu); document.addEventListener("keydown", closeOnEscape); return () => { document.removeEventListener("pointerdown", closeMenu); document.removeEventListener("keydown", closeOnEscape); }; }, [accountOpen]);
  const closeAccountMenu = () => { if (!accountOpen) return; setAccountMenuState("closing"); window.setTimeout(() => setAccountMenuState((state) => state === "closing" ? "closed" : state), 180); };
  const toggleAccountMenu = () => { if (accountOpen) closeAccountMenu(); else setAccountMenuState("open"); };
  const placeholder = { assessments: [admin ? "Assessments unavailable" : "Measure your skills", admin ? "Assessment management is available only in the student learning workspace." : "Published assessments and performance history will appear here."], vault: ["Career Vault", "Your resume sections and uploaded documents will appear here."], community: ["Community", "Posts, comments, and moderation activity will appear here."], resources: ["Learning resources", "Administrator-published resources will appear here."], events: ["Events", "Upcoming workshops and event registrations will appear here."], students: ["Student directory", "Registered student accounts will appear here."], settings: ["Platform settings", "Safe operational settings will appear here."] };
  const dashboard = <StudentOverview go={go} />;
  const content = admin && section === "overview" ? <AdminOverview go={go} />
    : admin && section === "profile" ? <AdminProfile />
    : admin && section === "students" ? <AdminStudents />
    : admin && section === "applications" ? <AdminApplications />
    : admin && section === "community" ? <AdminCommunity />
    : admin && ["resources", "events"].includes(section) ? <AdminContentManager kind={section} />
    : section === "overview" ? dashboard
    : section === "profile" && !admin ? <StudentProfile />
    : section === "assessments" && !admin ? <LearningPaths />
    : section === "resources" && !admin ? <StudentResources />
    : section === "events" && !admin ? <StudentEvents go={go} />
    : section === "community" && !admin ? <Community />
    : section === "connect" && !admin ? <Connect go={go} />
    : section === "chat" && !admin ? <StudentChat />
    : section === "vault" && !admin ? <CareerVault />
    : admin && section === "settings" ? <AdminSettings go={go} />
    : section === "jobs" ? admin ? <AdminJobs /> : <StudentJobs />
    : <EmptyPanel title={placeholder[section]?.[0] || label} copy={placeholder[section]?.[1] || "This section is ready for Spring Boot API data."} />;
  const signOut = () => { localStorage.removeItem("careerforge_session"); go("/"); };
  return <main className={`workspace ${admin ? "admin-workspace" : "student-workspace"}`}>
    <aside className="sidebar">
      <Brand onClick={() => go(`/${role}/overview`)} ariaLabel="Go to workspace overview" />
      <div className="sidebar-role">{admin ? "ADMIN WORKSPACE" : "STUDENT WORKSPACE"}</div>
      <nav>{items.map(([id, name, Icon]) => <button className={id === section ? "active" : ""} onClick={() => go(`/${role}/${id}`)} key={id}><Icon size={17} />{name}</button>)}</nav>
      <button className="signout" onClick={signOut}>Sign out</button>
    </aside>
    <div className="workspace-main">
      <header className="workspace-header">
        <div>{admin && <p className="breadcrumb">ADMINISTRATION</p>}<h1>{label}</h1></div>
        <div className="top-actions">
          <div className="workspace-search">
            <Search size={17} />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search workspace" aria-label="Search workspace" />
            {matches.length > 0 && <div className="search-results">{matches.map(([id, name, Icon]) => <button key={id} onClick={() => { go(`/${role}/${id}`); setQuery(""); }}><Icon size={15} />{name}</button>)}</div>}
            {query && matches.length === 0 && <div className="search-results no-results">No matching workspace section.</div>}
          </div>
          <div className="account-control">
            <button className="avatar" onClick={toggleAccountMenu} aria-expanded={accountOpen} aria-label="Open account menu">{current?.name?.slice(0, 1)?.toUpperCase() || (admin ? "A" : "S")}</button>
            {accountVisible && <div className={`account-menu ${accountMenuState === "closing" ? "is-closing" : ""}`} aria-hidden={!accountOpen}>
              <b>{current?.name || (admin ? "Administrator" : "Student")}</b>
              <small>{current?.email || "Local session"}</small>
              <button onClick={() => { closeAccountMenu(); go(`/${role}/profile`); }}>My profile</button>
              <button onClick={signOut}>Sign out</button>
            </div>}
          </div>
        </div>
      </header>
      {content}
    </div>
  </main>;
}

function App() {
  const [route, go] = useRoute();
  const storedSession = getSession();
  const storedRole = storedSession?.role === "admin" || storedSession?.role === "student" ? storedSession.role : null;
  useEffect(() => {
    if (route !== "/") return undefined;
    const frame = window.requestAnimationFrame(() => window.scrollTo({ top: 0, left: 0, behavior: "smooth" }));
    return () => window.cancelAnimationFrame(frame);
  }, [route]);
  useEffect(() => {
    const timeouts = new WeakMap();
    const dismiss = (toast) => {
      window.clearTimeout(timeouts.get(toast));
      toast.classList.add("toast-dismissed");
    };
    const prepareToast = (toast) => {
      const message = Array.from(toast.childNodes).filter((node) => node.nodeType === Node.TEXT_NODE).map((node) => node.textContent.trim()).join(" ");
      if (!message || toast.dataset.toastMessage === message) return;
      toast.dataset.toastMessage = message;
      toast.classList.remove("toast-dismissed");
      toast.setAttribute("role", toast.classList.contains("form-error") ? "alert" : "status");
      toast.setAttribute("aria-live", "polite");
      let close = toast.querySelector(".toast-close");
      if (!close) {
        close = document.createElement("button");
        close.type = "button";
        close.className = "toast-close";
        close.setAttribute("aria-label", "Dismiss notification");
        close.textContent = "×";
        close.addEventListener("click", () => dismiss(toast));
        toast.appendChild(close);
      }
      window.clearTimeout(timeouts.get(toast));
      timeouts.set(toast, window.setTimeout(() => dismiss(toast), 5000));
    };
    const findToasts = () => document.querySelectorAll(".form-success, .form-error").forEach(prepareToast);
    const observer = new MutationObserver(findToasts);
    findToasts();
    observer.observe(document.body, { childList: true, subtree: true, characterData: true });
    return () => { observer.disconnect(); document.querySelectorAll(".form-success, .form-error").forEach((toast) => window.clearTimeout(timeouts.get(toast))); };
  }, []);
  const pieces = route.split("/").filter(Boolean);
  const screen = pieces[0] === "login"
    ? <Login role={pieces[1] === "admin" ? "admin" : "student"} register={false} go={go} />
    : pieces[0] === "register"
      ? <Login role="student" register go={go} />
      : pieces[0] === "student" || pieces[0] === "admin"
        ? <Workspace role={pieces[0]} section={pieces[1] || "overview"} go={go} />
        : storedRole ? <Workspace role={storedRole} section="overview" go={go} /> : <FinpayLanding go={go} />;
  return <div className="route-transition" key={route}>{screen}</div>;
}
export default App;
